async function ensureApiLogTable(db) {
    await db.execute(`CREATE TABLE IF NOT EXISTS api_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL DEFAULT 0,
        username TEXT NOT NULL DEFAULT '',
        char_name TEXT NOT NULL DEFAULT '',
        method TEXT NOT NULL,
        path TEXT NOT NULL,
        status INTEGER NOT NULL DEFAULT 0,
        req_body TEXT,
        tab_viewed INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL
    )`);
}

// Stores lightweight per-minute "did a human interact" beacons from the client.
// Only a boolean is recorded (mouse/keyboard/touch seen or not) — no coordinates.
async function ensureInputActivityTable(db) {
    await db.execute(`CREATE TABLE IF NOT EXISTS input_activity (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        char_id INTEGER NOT NULL DEFAULT 0,
        char_name TEXT NOT NULL DEFAULT '',
        has_input INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL
    )`);
    try { await db.execute({ sql: "CREATE INDEX IF NOT EXISTS idx_input_activity_created ON input_activity(created_at)", args: [] }); } catch {}
}

async function ensureFlaggedTable(db) {
    await db.execute({ sql: `CREATE TABLE IF NOT EXISTS flagged_characters (id INTEGER PRIMARY KEY AUTOINCREMENT, char_name TEXT NOT NULL UNIQUE, reason TEXT NOT NULL DEFAULT '', detected_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, confirmed INTEGER NOT NULL DEFAULT 0, signal_count INTEGER NOT NULL DEFAULT 0, distinct_signals INTEGER NOT NULL DEFAULT 0, signal_types TEXT NOT NULL DEFAULT '')`, args: [] });
    // Migration: add signal tracking columns to existing tables
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN signal_count INTEGER NOT NULL DEFAULT 0", args: [] }); } catch {}
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN distinct_signals INTEGER NOT NULL DEFAULT 0", args: [] }); } catch {}
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN signal_types TEXT NOT NULL DEFAULT ''", args: [] }); } catch {}
    // Flag events log table
    try { await db.execute({ sql: `CREATE TABLE IF NOT EXISTS flag_events (id INTEGER PRIMARY KEY AUTOINCREMENT, char_name TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', signal_type TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL)`, args: [] }); } catch {}
    // Migration: scan_enabled toggle + scan_started_at
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN scan_enabled INTEGER NOT NULL DEFAULT 1", args: [] }); } catch {}
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN scan_notes TEXT NOT NULL DEFAULT ''", args: [] }); } catch {}
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN scan_started_at INTEGER NOT NULL DEFAULT 0", args: [] }); } catch {}
    // Migration: auto-ban escalation tracking for untrusted_api offenses
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN untrusted_offenses INTEGER NOT NULL DEFAULT 0", args: [] }); } catch {}
    try { await db.execute({ sql: "ALTER TABLE flagged_characters ADD COLUMN last_untrusted_at INTEGER NOT NULL DEFAULT 0", args: [] }); } catch {}
}

const UNTRUSTED_API_DEBOUNCE_S = 300; // 5 min — a burst of reports counts as one offense
const UNTRUSTED_API_BAN_MINUTES = [60, 720, 1440]; // 1h, 12h, 24h

async function autoBanUntrustedApi(db, userId, charName, detail) {
    try {
        await ensureFlaggedTable(db);
        const now = Math.floor(Date.now() / 1000);
        const row = await dbGet(db, 'SELECT untrusted_offenses, last_untrusted_at FROM flagged_characters WHERE char_name=?', [charName]);
        const lastAt = row?.last_untrusted_at || 0;
        let offenses = row?.untrusted_offenses || 0;

        // Debounce: ignore additional reports from the same offending burst/session.
        const isNewOffense = (now - lastAt) > UNTRUSTED_API_DEBOUNCE_S;
        if (isNewOffense) offenses += 1;

        await db.execute({ sql: 'UPDATE flagged_characters SET untrusted_offenses=?, last_untrusted_at=? WHERE char_name=?', args: [offenses, now, charName] });

        // Determine ban for THIS offense (if it's a new/current offense apply it).
        const offenseIdx = offenses - 1;
        let banLevel = 2;
        let expiresAt = now + UNTRUSTED_API_BAN_MINUTES[Math.min(offenseIdx, UNTRUSTED_API_BAN_MINUTES.length - 1)] * 60;
        if (offenses >= UNTRUSTED_API_BAN_MINUTES.length + 1) { // 4th offense -> permanent
            banLevel = 3;
            expiresAt = null;
        }
        const reason = offenses >= UNTRUSTED_API_BAN_MINUTES.length + 1
            ? 'Auto-Ban: Repeated scripting detected'
            : `Auto-Ban: Scripting detected (offense #${offenses})`;
        await dbRun(db, 'UPDATE users SET ban_level=?, ban_expires_at=?, ban_reason=?, banned_by=? WHERE id=?', [banLevel, expiresAt, reason, 0, userId]);
        await logFlagEvent(db, charName, reason, 'untrusted_api_autoban');
        if (banLevel === 3) {
            console.log(`🚫 [AUTO-BAN] ${charName} permanently banned for repeated untrusted API calls (${offenses} offenses)`);
        } else {
            console.log(`🔒 [AUTO-BAN] ${charName} locked for ${Math.round(UNTRUSTED_API_BAN_MINUTES[Math.min(offenseIdx, UNTRUSTED_API_BAN_MINUTES.length - 1)] / 60)}h on untrusted API offense #${offenses}`);
        }
    } catch (e) { console.error('[autoBanUntrustedApi]', e.message); }
}

async function logFlagEvent(db, charName, reason, signalType) {
    try { await db.execute({ sql: `INSERT INTO flag_events (char_name, reason, signal_type, created_at) VALUES (?,?,?,?)`, args: [charName, String(reason).slice(0, 500), String(signalType).slice(0, 100), Math.floor(Date.now()/1000)] }); } catch {}
}

router.use(async (req, res, next) => {
    const start = Date.now();
    res.on('finish', async () => {
        try {
            const db = await getDb();
            await ensureApiLogTable(db);
            const now = Math.floor(Date.now() / 1000);
            const userId = req.user?.userId || 0;
            const username = req.user?.username || '';
            const path = req.originalUrl || req.url;
            // Skip logging chat/admin endpoints to avoid cluttering api_log
            if (path.includes('/chat/') || path.includes('/admin/')) return;
            let charName = '';
            try {
                const char = await dbGet(db, 'SELECT name FROM characters WHERE (SELECT active_character_id FROM users WHERE id=?) = id', [userId]);
                if (char) charName = char.name;
            } catch {}
            const lastTab = _missionsTabView.get(userId) || 0;
            // tab_viewed only matters for mission endpoints (generous 24h window)
            const isMissionPath = path.includes('/missions/start') || path.includes('/missions/collect') || path.includes('/missions/tab-viewed');
            const tabViewed = isMissionPath ? ((now - lastTab) < 86400 ? 1 : 0) : 1;
            let bodyStr = '';
            if (req.body && typeof req.body === 'object' && Object.keys(req.body).length) {
                bodyStr = JSON.stringify(req.body);
                if (bodyStr.length > 500) bodyStr = bodyStr.substring(0, 500);
            }
            const result = await db.execute({
                sql: `INSERT INTO api_log (user_id, username, char_name, method, path, status, req_body, tab_viewed, created_at) VALUES (?,?,?,?,?,?,?,?,?)`,
                args: [userId, username, charName, req.method, path, res.statusCode, bodyStr, tabViewed, now]
            });
            // Maintain 500 most recent entries per character (circular buffer)
            if (charName && result.lastInsertRowid) {
                try {
                    await db.execute({
                        sql: `DELETE FROM api_log WHERE char_name = ? AND id NOT IN (SELECT id FROM api_log WHERE char_name = ? ORDER BY id DESC LIMIT 500)`,
                        args: [charName, charName]
                    });
                } catch {}
            }
        } catch {}
    });
    next();
});

