// ── Stale client detection middleware ──────────────────────────────────────
const BUILD_VERSION = '2026-07-09-v1';
router.use((req, res, next) => {
    if (req.method === 'OPTIONS') return next();
    const clientVersion = req.headers['x-build-version'];
    const path = req.path;
    // Only check game routes (not static files)
    if (clientVersion && clientVersion !== BUILD_VERSION && path.startsWith('/api/game/') && !path.startsWith('/api/game/auth/')) {
        (async () => {
            try {
                const db = await getDb();
                const char = req.user ? await getCurrentCharacter(db, req.user.userId, 'id, name').catch(() => null) : null;
                await db.execute({
                    sql: `INSERT INTO stale_clients (user_id, char_name, version, path, created_at) VALUES (?,?,?,?,?)`,
                    args: [req.user?.userId || 0, char?.name || '', clientVersion || 'unknown', path, Math.floor(Date.now()/1000)]
                });
            } catch (e) {}
        })();
    }
    next();
});

function parseAdminPassword(req) {
    const h = req.headers && req.headers['x-admin-password'];
    if (h) return String(h).trim();
    return String(req.body?.password || req.query?.password || '').trim();
}

// Avoid leaking the admin password in the URL via the Referer header.
const noReferrer = (req, res, next) => { res.set('Referrer-Policy', 'no-referrer'); next(); };

// ── Admin password brute-force protection (per-IP, DB-persisted) ─────────
const ADMIN_FAIL_WINDOW_MS = 10 * 60 * 1000;   // failure counter window
const ADMIN_FAIL_MAX = 5;                      // wrong attempts before temp ban
const ADMIN_BAN_MS = 15 * 60 * 1000;           // temp ban duration
const adminPwFailures = new Map();             // short-lived failure counters
const adminPwBans = new Map();                 // in-memory cache of active bans
let adminBanTableReady = false;
let lastBanPurge = 0;

async function ensureAdminBanTable() {
    try {
        const db = await getDb();
        if (!adminBanTableReady) {
            await db.execute({ sql: `CREATE TABLE IF NOT EXISTS admin_ip_bans (
                ip TEXT PRIMARY KEY,
                banned_until INTEGER NOT NULL,
                created_at INTEGER NOT NULL,
                reason TEXT NOT NULL DEFAULT ''
            )` });
            adminBanTableReady = true;
        }
        if (Date.now() - lastBanPurge > 3600000) {
            lastBanPurge = Date.now();
            await db.execute({ sql: 'DELETE FROM admin_ip_bans WHERE banned_until < ?', args: [Date.now()] }).catch(() => {});
        }
    } catch {}
}

function getClientIp(req) {
    return String(req.ip || req.connection?.remoteAddress || req.headers['x-forwarded-for']?.split(',')[0] || 'unknown').slice(0, 45);
}

async function adminIpStatus(ip) {
    const now = Date.now();
    const inMem = adminPwBans.get(ip);
    if (inMem && inMem > now) return { banned: true, until: inMem };
    const rec = adminPwFailures.get(ip);
    if (rec && rec.bannedUntil && rec.bannedUntil > now) return { banned: true, until: rec.bannedUntil };
    try {
        await ensureAdminBanTable();
        const db = await getDb();
        const row = await dbGet(db, 'SELECT banned_until FROM admin_ip_bans WHERE ip = ?', [ip]);
        if (row && Number(row.banned_until) > now) {
            adminPwBans.set(ip, Number(row.banned_until)); // warm cache
            return { banned: true, until: Number(row.banned_until) };
        }
    } catch {}
    return { banned: false };
}

async function persistBan(ip, until, reason) {
    try {
        await ensureAdminBanTable();
        const db = await getDb();
        await dbRun(db, 'INSERT OR REPLACE INTO admin_ip_bans (ip, banned_until, created_at, reason) VALUES (?,?,?,?)',
            [ip, until, Math.floor(Date.now() / 1000), reason]);
    } catch {}
    adminPwBans.set(ip, until);
}

async function recordAdminFailure(ip) {
    const now = Date.now();
    let rec = adminPwFailures.get(ip) || { count: 0, windowStart: now, bannedUntil: 0 };
    if (now - rec.windowStart > ADMIN_FAIL_WINDOW_MS) rec = { count: 0, windowStart: now, bannedUntil: 0 };
    rec.count += 1;
    if (rec.count >= ADMIN_FAIL_MAX) {
        rec.bannedUntil = now + ADMIN_BAN_MS;
        rec.count = 0;
        console.warn(`[admin-pw] IP ${ip} banned for ${Math.round(ADMIN_BAN_MS/60000)}min after too many attempts`);
        await persistBan(ip, rec.bannedUntil, 'auto: too many admin-password attempts');
    }
    adminPwFailures.set(ip, rec);
}

function clearAdminFailure(ip) { adminPwFailures.delete(ip); }

async function banAdminIp(ip, minutes, reason) {
    const until = Date.now() + minutes * 60 * 1000;
    console.warn(`[admin-pw] manual ban: ${ip} for ${minutes}min`);
    await persistBan(ip, until, reason || 'manual');
    return until;
}

async function unbanAdminIp(ip) {
    try {
        const db = await getDb();
        await dbRun(db, 'DELETE FROM admin_ip_bans WHERE ip = ?', [ip]).catch(() => {});
    } catch {}
    adminPwBans.delete(ip);
    adminPwFailures.delete(ip);
}

// Evaluate an admin-password request. Returns null when allowed, or
// { status, message } to short-circuit with an error (banned only — a plain
// wrong password returns null so the route keeps its own response/redirect).
async function adminPasswordCheck(req, ok) {
    const ip = getClientIp(req);
    if ((await adminIpStatus(ip)).banned) {
        return { status: 429, message: 'Too many attempts. This IP is temporarily blocked.' };
    }
    if (ok) { clearAdminFailure(ip); return null; }
    await recordAdminFailure(ip);
    if ((await adminIpStatus(ip)).banned) {
        return { status: 429, message: 'Too many attempts. This IP is temporarily blocked.' };
    }
    return null;
}

function escapeRegex(text) {
    return String(text || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function maskProfanityWord(word) {
    const clean = String(word || '');
    if (clean.length <= 2) return '*'.repeat(clean.length || 1);
    return `${clean[0]}${'*'.repeat(Math.max(1, clean.length - 2))}${clean[clean.length - 1]}`;
}

function sanitizeChatMessage(input) {
    let text = String(input || '').replace(/\s+/g, ' ').trim();
    if (!text) return '';
    if (text.length > CHAT_MESSAGE_MAX_LENGTH) {
        text = text.slice(0, CHAT_MESSAGE_MAX_LENGTH).trim();
    }
    for (const bannedWord of CHAT_PROFANITY_WORDS) {
        const re = new RegExp(`\\b${escapeRegex(bannedWord)}\\b`, 'gi');
        text = text.replace(re, (match) => maskProfanityWord(match));
    }
    return text;
}

function normalizeCharacterName(input) {
    return String(input || '').replace(/\s+/g, ' ').trim();
}

function containsProfanity(input) {
    const text = String(input || '');
    if (!text) return false;
    for (const bannedWord of CHAT_PROFANITY_WORDS) {
        const re = new RegExp(`\\b${escapeRegex(bannedWord)}\\b`, 'i');
        if (re.test(text)) return true;
    }
    return false;
}

function isTutorialCharacter(char) {
    if (!char) return false;
    return Number(char.wins || 0) < 4 && !Number(char.tutorial_skipped || 0);
}

function serializeChatMessage(row, currentCharId) {
    return {
        id: Number(row.id || 0),
        sender_char_id: Number(row.sender_char_id || 0),
        sender_name: row.sender_name || 'Unknown',
        recipient_char_id: row.recipient_char_id ? Number(row.recipient_char_id) : null,
        recipient_name: row.recipient_name || null,
        message_text: row.message_text || '',
        created_at: Number(row.created_at || 0),
        edited: !!row.edited,
        edited_at: row.edited_at ? Number(row.edited_at) : null,
        is_private: !!row.recipient_char_id,
        squad_id: row.squad_id ? Number(row.squad_id) : null,
        is_outgoing: Number(row.sender_char_id || 0) === Number(currentCharId || 0)
    };
}

function buildAdminRewardPayload(input = {}) {
    const gold = Math.max(0, Number(input.gold || 0));
    const gems = Math.max(0, Number(input.gems || 0));
    const xp = Math.max(0, Number(input.xp || 0));
    const materialType = String(input.materialType || '').trim().toLowerCase();
    const materialId = normalizeRewardMaterialId(input.materialId);
    const materialQty = Math.max(0, Number(input.materialQty || 0));
    const payload = {};
    if (gold > 0) payload.gold = gold;
    if (gems > 0) payload.gems = gems;
    if (xp > 0) payload.xp = xp;
    if (materialId && materialQty > 0 && (materialType === 'raw_mat' || materialType === 'component')) {
        payload.material = { type: materialType, id: materialId, qty: materialQty };
    }
    return Object.keys(payload).length ? payload : null;
}

function adminRewardInputLooksFilled(input = {}) {
    const values = [
        input.gold,
        input.gems,
        input.xp,
        input.materialType,
        input.materialId,
        input.materialQty
    ];
    return values.some(v => String(v ?? '').trim() !== '' && String(v ?? '').trim() !== '0');
}

function describeAdminRewardPayload(payload) {
    if (!payload || typeof payload !== 'object') return 'Message only';
    const parts = [];
    if (payload.gold) parts.push(`${Number(payload.gold).toLocaleString()} gold`);
    if (payload.gems) parts.push(`${Number(payload.gems).toLocaleString()} gems`);
    if (payload.xp) parts.push(`${Number(payload.xp).toLocaleString()} XP`);
    if (payload.raidTokens) parts.push(`${Number(payload.raidTokens).toLocaleString()} Raid Tokens`);
    if (payload.material?.id && payload.material?.qty) parts.push(`${Number(payload.material.qty).toLocaleString()}x ${payload.material.id}`);
    return parts.length ? parts.join(' + ') : 'Message only';
}

async function purgeExpiredMessages(db) {
    const cutoff = Math.floor(Date.now() / 1000) - MESSAGE_RETENTION_SECONDS;
    await dbRun(db, 'DELETE FROM messages WHERE sent_at < ?', [cutoff]);
}

async function purgeExpiredChatMessages(db) {
    const cutoff = Math.floor(Date.now() / 1000) - CHAT_RETENTION_SECONDS;
    await dbRun(db, 'DELETE FROM chat_messages WHERE created_at < ?', [cutoff]);
}

async function hideOldMissionReports(db, charId, keepCount = 10) {
    const allReports = await dbAll(db,
        "SELECT id, body FROM messages WHERE receiver_id = ? AND body LIKE 'BATTLE_REPORT:%' AND hidden=0 ORDER BY sent_at DESC",
        [charId]
    );
    const missionIds = [];
    for (const row of allReports) {
        try {
            const payload = JSON.parse(row.body.slice('BATTLE_REPORT:'.length));
            if (payload.type === 'mission') missionIds.push(row.id);
        } catch {}
    }
    if (missionIds.length <= keepCount) return;
    const toHide = missionIds.slice(keepCount);
    for (const id of toHide) {
        await dbRun(db, 'UPDATE messages SET hidden=1 WHERE id=?', [id]);
    }
}

async function purgeOldApiLogs(db) {
    const cutoff = Math.floor(Date.now() / 1000) - 86400 * 7;
    await dbRun(db, 'DELETE FROM api_log WHERE created_at < ?', [cutoff]);
}

async function purgeOldDomMutations(db) {
    const cutoff = Math.floor(Date.now() / 1000) - 86400 * 7;
    await dbRun(db, 'DELETE FROM dom_mutations WHERE created_at < ?', [cutoff]);
}

async function purgeOldCspViolations(db) {
    await dbRun(db, "DELETE FROM csp_violations WHERE reported_at < datetime('now', '-7 days')");
}

async function purgeOldFlagEvents(db) {
    const cutoff = Math.floor(Date.now() / 1000) - 86400 * 14;
    await dbRun(db, 'DELETE FROM flag_events WHERE created_at < ?', [cutoff]);
}

async function purgeOldInputActivity(db) {
    const cutoff = Math.floor(Date.now() / 1000) - 86400 * 3;
    await dbRun(db, 'DELETE FROM input_activity WHERE created_at < ?', [cutoff]);
}

async function purgeAllOldData(db) {
    try { await purgeExpiredMessages(db); } catch (e) { console.error('[purge] messages:', e.message); }
    try { await purgeExpiredChatMessages(db); } catch (e) { console.error('[purge] chat:', e.message); }
    try { await purgeOldApiLogs(db); } catch (e) { console.error('[purge] api_log:', e.message); }
    try { await purgeOldDomMutations(db); } catch (e) { console.error('[purge] dom_mutations:', e.message); }
    try { await purgeOldCspViolations(db); } catch (e) { console.error('[purge] csp_violations:', e.message); }
    try { await purgeOldFlagEvents(db); } catch (e) { console.error('[purge] flag_events:', e.message); }
    try { await purgeOldInputActivity(db); } catch (e) { console.error('[purge] input_activity:', e.message); }
    // Ensure indexes exist for cleanup queries
    try { await dbRun(db, "CREATE INDEX IF NOT EXISTS idx_api_log_created ON api_log(created_at)"); } catch {}
    try { await dbRun(db, "CREATE INDEX IF NOT EXISTS idx_dom_mutations_created ON dom_mutations(created_at)"); } catch {}
    try { await dbRun(db, "CREATE INDEX IF NOT EXISTS idx_flag_events_created ON flag_events(created_at)"); } catch {}
    try { await dbRun(db, "CREATE INDEX IF NOT EXISTS idx_input_activity_created ON input_activity(created_at)"); } catch {}
    try { await dbRun(db, "CREATE INDEX IF NOT EXISTS idx_messages_sent ON messages(sent_at)"); } catch {}
    try { await dbRun(db, "CREATE INDEX IF NOT EXISTS idx_chat_messages_created ON chat_messages(created_at)"); } catch {}
}

async function queueReferralRewards(db, userId, rewards = {}) {
    if (!userId) return;
    const gold = Math.max(0, Number(rewards.gold || 0));
    const gems = Math.max(0, Number(rewards.gems || 0));
    const registered = Math.max(0, Number(rewards.registered || 0));
    const level5 = Math.max(0, Number(rewards.level5 || 0));
    await dbRun(
        db,
        `UPDATE users
         SET pending_referral_gold = COALESCE(pending_referral_gold, 0) + ?,
             pending_referral_gems = COALESCE(pending_referral_gems, 0) + ?,
             referrals_registered = COALESCE(referrals_registered, 0) + ?,
             referrals_level5 = COALESCE(referrals_level5, 0) + ?
         WHERE id = ?`,
        [gold, gems, registered, level5, userId]
    );
}

async function handleReferralLevelMilestone(db, userId, previousLevel, newLevel) {
    if (!userId || Number(previousLevel || 0) >= 5 || Number(newLevel || 0) < 5) return;
    const user = await dbGet(db, 'SELECT id, referred_by_user_id, referral_level5_rewarded FROM users WHERE id = ?', [userId]);
    if (!user || !user.referred_by_user_id || Number(user.referral_level5_rewarded || 0) !== 0) return;
    await queueReferralRewards(db, user.referred_by_user_id, { gems: 5, level5: 1 });
    await dbRun(db, 'UPDATE users SET referral_level5_rewarded = 1 WHERE id = ?', [user.id]);
}

function getScaledForgeGoldCost(baseGoldCost, playerLevel, minLevel = 1) {
    const base = Math.max(0, Number(baseGoldCost || 0));
    const lvl = Math.max(1, Number(playerLevel || 1));
    const minLvl = Math.max(1, Number(minLevel || 1));
    const levelDiff = Math.max(0, lvl - minLvl);
    const scale = 1 + (levelDiff * 0.20);
    return Math.max(0, Math.floor(base * scale));
}

