router.post('/squads/leave', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id, role FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        if (!membership) return res.json({ success: true });
        // If leader leaves, transfer ownership to oldest co-leader, officer, or member.
        if (membership.role === 'leader') {
            let successor = await dbGet(db, "SELECT char_id FROM squad_members WHERE squad_id=? AND role='co_leader' AND char_id!=? ORDER BY joined_at ASC LIMIT 1", [membership.squad_id, char.id]);
            if (!successor) {
                successor = await dbGet(db, "SELECT char_id FROM squad_members WHERE squad_id=? AND role='officer' AND char_id!=? ORDER BY joined_at ASC LIMIT 1", [membership.squad_id, char.id]);
            }
            if (!successor) {
                successor = await dbGet(db, "SELECT char_id FROM squad_members WHERE squad_id=? AND char_id!=? ORDER BY joined_at ASC LIMIT 1", [membership.squad_id, char.id]);
            }
            if (successor) {
                await dbRun(db, 'UPDATE squads SET owner_char_id=? WHERE id=?', [successor.char_id, membership.squad_id]);
                await dbRun(db, "UPDATE squad_members SET role='leader' WHERE char_id=? AND squad_id=?", [successor.char_id, membership.squad_id]);
            } else {
                // No officers — just delete the whole squad.
                await dbRun(db, 'DELETE FROM squad_members WHERE squad_id=?', [membership.squad_id]);
                await dbRun(db, 'UPDATE clan_bases SET owner_squad_id=NULL, occupied_at=NULL WHERE owner_squad_id=?', [membership.squad_id]);
                await dbRun(db, 'DELETE FROM squads WHERE id=?', [membership.squad_id]);
                return res.json({ success: true, message: 'Squad disbanded.' });
            }
        }
        await dbRun(db, 'DELETE FROM squad_members WHERE char_id=?', [char.id]);
        const left = await dbGet(db, 'SELECT COUNT(*) AS c FROM squad_members WHERE squad_id=?', [membership.squad_id]);
        if (Number(left?.c || 0) <= 0) {
            await dbRun(db, 'UPDATE clan_bases SET owner_squad_id=NULL, occupied_at=NULL WHERE owner_squad_id=?', [membership.squad_id]);
            await dbRun(db, 'DELETE FROM squads WHERE id=?', [membership.squad_id]);
        }
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.get('/squads/leaderboard', auth, async (req, res) => {
    try {
        const db = await getDb();
        // Use lifetime total_gold_earned for "cumulative gold".
        const rows = await dbAll(db, `
            SELECT
                s.id,
                s.name,
                s.squad_tag,
                s.logo,
                COUNT(sm.char_id) AS member_count,
                CAST(AVG(c.level) AS INTEGER) AS avg_level,
                CAST(AVG(c.total_gold_earned) AS INTEGER) AS avg_gold_earned,
                SUM(c.total_gold_earned) AS total_gold_earned
            FROM squads s
            JOIN squad_members sm ON sm.squad_id = s.id
            JOIN characters c ON c.id = sm.char_id
            GROUP BY s.id
            ORDER BY total_gold_earned DESC
            LIMIT 200
        `, []);
        res.json(rows.map(r => ({
            id: Number(r.id || 0),
            name: r.name,
            tag: r.squad_tag || null,
            squad_tag: r.squad_tag || null,
            logo: r.logo || null,
            member_count: Number(r.member_count || 0),
            avg_level: Number(r.avg_level || 0),
            avg_gold_earned: Number(r.avg_gold_earned || 0),
            total_gold_earned: Number(r.total_gold_earned || 0),
        })));
    } catch (e) { res.status(500).json({ error: e.message }); }
});

