router.post('/squads/applications/:appId/accept', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, "SELECT squad_id FROM squad_members WHERE char_id=? AND role IN ('leader','co_leader','officer') LIMIT 1", [char.id]);
        if (!membership) return res.status(403).json({ error: 'Only squad leaders, co-leaders and officers can accept applications.' });
        const appId = Number(req.params.appId);
        const app = await dbGet(db, 'SELECT * FROM squad_applications WHERE id=? AND squad_id=? AND status=?', [appId, membership.squad_id, 'pending']);
        if (!app) return res.status(404).json({ error: 'Application not found.' });
        const alreadyMember = await dbGet(db, 'SELECT 1 FROM squad_members WHERE char_id=? LIMIT 1', [app.char_id]);
        if (alreadyMember) {
            await dbRun(db, "UPDATE squad_applications SET status='rejected' WHERE id=?", [appId]);
            return res.status(400).json({ error: 'Applicant is already in a squad.' });
        }
        const appChar = await dbGet(db, 'SELECT id FROM characters WHERE id=?', [app.char_id]);
        if (!appChar) {
            await dbRun(db, "UPDATE squad_applications SET status='rejected' WHERE id=?", [appId]);
            return res.status(400).json({ error: 'Applicant character no longer exists.' });
        }
        const now = Math.floor(Date.now() / 1000);
        await dbRun(db, 'INSERT INTO squad_members (squad_id, char_id, role, joined_at) VALUES (?,?,?,?)', [membership.squad_id, app.char_id, 'member', now]);
        await dbRun(db, "UPDATE squad_applications SET status='accepted' WHERE id=?", [appId]);
        await dbRun(db, 'INSERT INTO messages (sender_id,receiver_id,subject,body) VALUES (?,?,?,?)', [char.id, app.char_id, '✅ Squad Application Accepted', `You have been accepted into the squad!`]);
        res.json({ success: true });
    } catch (e) {
        if (e.code === 'SQLITE_CONSTRAINT' || e.code === 'SQLITE_CONSTRAINT_FOREIGNKEY') {
            return res.status(400).json({ error: 'Could not add member — the character may have been deleted.' });
        }
        res.status(500).json({ error: e.message });
    }
});

router.post('/squads/applications/:appId/reject', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, "SELECT squad_id FROM squad_members WHERE char_id=? AND role IN ('leader','co_leader','officer') LIMIT 1", [char.id]);
        if (!membership) return res.status(403).json({ error: 'Only squad leaders, co-leaders and officers can reject applications.' });
        const appId = Number(req.params.appId);
        const app = await dbGet(db, 'SELECT * FROM squad_applications WHERE id=? AND squad_id=? AND status=?', [appId, membership.squad_id, 'pending']);
        if (!app) return res.status(404).json({ error: 'Application not found.' });
        await dbRun(db, "UPDATE squad_applications SET status='rejected' WHERE id=?", [appId]);
        await dbRun(db, 'INSERT INTO messages (sender_id,receiver_id,subject,body) VALUES (?,?,?,?)', [char.id, app.char_id, '❌ Squad Application Rejected', `Your squad application was not accepted.`]);
        res.json({ success: true });
    } catch (e) {
        if (e.code === 'SQLITE_CONSTRAINT' || e.code === 'SQLITE_CONSTRAINT_FOREIGNKEY') {
            return res.status(400).json({ error: 'Could not send notification — the applicant may have been deleted.' });
        }
        res.status(500).json({ error: e.message });
    }
});

// ── Squad Role Management ───────────────────────────────────────────

router.post('/squads/members/:charId/role', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id, role FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        if (!membership) return res.status(403).json({ error: 'You are not in a squad.' });
        const targetId = Number(req.params.charId);
        if (!targetId) return res.status(400).json({ error: 'Invalid character ID.' });
        if (targetId === char.id) return res.status(400).json({ error: 'You cannot change your own role.' });
        const { role } = req.body;
        if (!role || !['co_leader', 'officer', 'member'].includes(role)) return res.status(400).json({ error: 'Role must be "co_leader", "officer", or "member".' });
        const target = await dbGet(db, 'SELECT role FROM squad_members WHERE char_id=? AND squad_id=? LIMIT 1', [targetId, membership.squad_id]);
        if (!target) return res.status(404).json({ error: 'Member not found in your squad.' });
        // Authorization
        if (membership.role === 'leader') {
            // Leader can assign any role
        } else if (membership.role === 'co_leader') {
            if (target.role === 'leader' || target.role === 'co_leader') {
                return res.status(403).json({ error: 'Co-leaders cannot change roles of leaders or other co-leaders.' });
            }
            if (role === 'co_leader') {
                return res.status(403).json({ error: 'Only the squad leader can promote to co-leader.' });
            }
        } else {
            return res.status(403).json({ error: 'Only leaders and co-leaders can assign roles.' });
        }
        await dbRun(db, 'UPDATE squad_members SET role=? WHERE char_id=? AND squad_id=?', [role, targetId, membership.squad_id]);
        await dbRun(db, 'INSERT INTO messages (sender_id,receiver_id,subject,body) VALUES (?,?,?,?)', [char.id, targetId, '🔰 Squad Role Changed', `Your role has been changed to "${role}".`]);
        res.json({ success: true, role });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Squad Invite Code Reset ─────────────────────────────────────────

router.post('/squads/members/:charId/kick', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id, role FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        if (!membership) return res.status(403).json({ error: 'You are not in a squad.' });
        const targetId = Number(req.params.charId);
        if (!targetId) return res.status(400).json({ error: 'Invalid character ID.' });
        if (targetId === char.id) return res.status(400).json({ error: 'You cannot kick yourself.' });
        const target = await dbGet(db, 'SELECT role FROM squad_members WHERE char_id=? AND squad_id=? LIMIT 1', [targetId, membership.squad_id]);
        if (!target) return res.status(404).json({ error: 'Member not found in your squad.' });
        // Authorization: leader can kick anyone; co-leader can kick officers and members; officer can kick members only
        if (membership.role === 'officer' && target.role !== 'member') {
            return res.status(403).json({ error: 'Officers can only kick members.' });
        }
        if (membership.role === 'co_leader' && (target.role === 'leader' || target.role === 'co_leader')) {
            return res.status(403).json({ error: 'Co-leaders cannot kick leaders or other co-leaders.' });
        }
        if (membership.role === 'member') {
            return res.status(403).json({ error: 'Only leaders, co-leaders and officers can kick members.' });
        }
        await dbRun(db, 'DELETE FROM squad_members WHERE char_id=? AND squad_id=?', [targetId, membership.squad_id]);
        await dbRun(db, 'INSERT INTO messages (sender_id,receiver_id,subject,body) VALUES (?,?,?,?)', [char.id, targetId, '👢 Kicked from Squad', `You have been kicked from the squad by ${char.name}.`]);
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post('/squads/reset-invite', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const squad = await dbGet(db, 'SELECT id FROM squads WHERE owner_char_id=? LIMIT 1', [char.id]);
        if (!squad) return res.status(403).json({ error: 'Only the squad leader can reset the invite code.' });
        let code = makeInviteCode();
        for (let i = 0; i < 5; i++) {
            const exists = await dbGet(db, 'SELECT 1 FROM squads WHERE invite_code=? AND id!=? LIMIT 1', [code, squad.id]);
            if (!exists) break;
            code = makeInviteCode();
        }
        await dbRun(db, 'UPDATE squads SET invite_code=? WHERE id=?', [code, squad.id]);
        res.json({ success: true, invite_code: code });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post('/squads/logo', auth, uploadLimiter, (req, res) => {
    uploadLogo(req, res, async (err) => {
        try {
            if (err) return res.status(400).json({ error: err.message || 'Upload failed' });
            const db = await getDb();
            const char = await getCurrentCharacter(db, req.user.userId, 'id');
            if (!char) return res.status(404).json({ error: 'No character' });
            const membership = await dbGet(db, "SELECT squad_id, role FROM squad_members WHERE char_id=? AND role IN ('leader','co_leader') LIMIT 1", [char.id]);
            if (!membership) return res.status(403).json({ error: 'Only the squad leader or co-leader can change the logo.' });
            if (!req.file) return res.status(400).json({ error: 'No file uploaded.' });
            if (!isRealImageFile(req.file.path)) {
                try { fs.unlinkSync(req.file.path); } catch {}
                return res.status(400).json({ error: 'Uploaded file is not a valid image.' });
            }

            // Delete old logo file if exists
            const old = await dbGet(db, 'SELECT logo FROM squads WHERE id=?', [membership.squad_id]);
            if (old?.logo && !old.logo.startsWith('data:')) {
                const oldPath = path.join(__dirname, '../public', old.logo);
                if (fs.existsSync(oldPath)) fs.unlinkSync(oldPath);
            }

            const logoUrl = '/images/squads/' + req.file.filename;
            await dbRun(db, 'UPDATE squads SET logo=? WHERE id=?', [logoUrl, membership.squad_id]);
            res.json({ success: true, logo: logoUrl });
        } catch (e) { res.status(500).json({ error: e.message }); }
    });
});

router.delete('/squads/logo', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, "SELECT squad_id, role FROM squad_members WHERE char_id=? AND role IN ('leader','co_leader') LIMIT 1", [char.id]);
        if (!membership) return res.status(403).json({ error: 'Only the squad leader or co-leader can remove the logo.' });

        // Delete the file
        const old = await dbGet(db, 'SELECT logo FROM squads WHERE id=?', [membership.squad_id]);
        if (old?.logo && !old.logo.startsWith('data:')) {
            const oldPath = path.join(__dirname, '../public', old.logo);
            if (fs.existsSync(oldPath)) fs.unlinkSync(oldPath);
        }

        await dbRun(db, 'UPDATE squads SET logo=NULL WHERE id=?', [membership.squad_id]);
        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Clan Base System ─────────────────────────────────────────────────────

router.get('/squads/bases', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        const squadId = membership?.squad_id || null;
        // Map is locked while the squad has an active war
        const inWar = squadId ? await dbGet(db, "SELECT 1 FROM clan_wars WHERE (attacker_squad_id=? OR defender_squad_id=?) AND status IN ('preparation','attacking') LIMIT 1", [squadId, squadId]) : null;
        const bases = await dbAll(db, `SELECT b.*, su.upgrade_level, su.last_upkeep_paid, s.name AS owner_name, s.squad_tag AS owner_tag
            FROM clan_bases b LEFT JOIN squad_base_upgrades su ON su.base_id = b.id AND su.squad_id = b.owner_squad_id
            LEFT JOIN squads s ON s.id = b.owner_squad_id ORDER BY b.tier, b.id`, []);
        const enhanced = bases.map(b => ({
            id: Number(b.id), name: b.name, tier: b.tier, max_upgrades: Number(b.max_upgrades),
            map_x: Number(b.map_x), map_y: Number(b.map_y),
            owner_squad_id: Number(b.owner_squad_id || 0),
            owner_name: b.owner_name || null,
            owner_tag: b.owner_tag || null,
            upgrade_level: Number(b.upgrade_level || 0),
            is_owner: squadId && Number(b.owner_squad_id || 0) === squadId,
            discount_pct: b.owner_squad_id && Number(b.upgrade_level || 0) > 0
                ? calcMemberStatDiscount(b.tier, Number(b.upgrade_level || 0), Number(b.last_upkeep_paid || 0)) : 0,
            upgrade_cost: b.owner_squad_id && squadId && Number(b.owner_squad_id) === squadId
                ? calcBaseUpgradeCost(b.tier, Number(b.upgrade_level || 0)) : null,
        }));
        // Which squads are currently at war, and their earliest resolve time
        const warSquads = new Map();
        for (const w of await dbAll(db, "SELECT attacker_squad_id, defender_squad_id, attack_ends_at FROM clan_wars WHERE status IN ('preparation','attacking')")) {
            const t = Number(w.attack_ends_at || 0);
            for (const sid of [Number(w.attacker_squad_id || 0), Number(w.defender_squad_id || 0)]) {
                if (sid <= 0) continue;
                if (!warSquads.has(sid) || (t > 0 && t < warSquads.get(sid))) warSquads.set(sid, t);
            }
        }
        for (const b of enhanced) {
            const ws = b.owner_squad_id ? warSquads.get(b.owner_squad_id) : undefined;
            b.owner_at_war = ws !== undefined;
            b.war_resolves_at = ws ? ws * 1000 : 0;
        }
        res.json({ bases: enhanced, squad_id: squadId, in_war: !!inWar });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post('/squads/bases/:baseId/donate', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId);
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        if (!membership) return res.status(403).json({ error: 'You are not in a squad.' });
        const baseId = Number(req.params.baseId);
        const base = await dbGet(db, 'SELECT * FROM clan_bases WHERE id=?', [baseId]);
        if (!base) return res.status(404).json({ error: 'Base not found.' });
        if (Number(base.owner_squad_id || 0) !== membership.squad_id) return res.status(403).json({ error: 'Your squad does not own this base.' });
        let { gold, gems } = req.body;
        gold = Math.max(0, Math.floor(Number(gold || 0)));
        gems = Math.max(0, Math.floor(Number(gems || 0)));
        if (gold <= 0 && gems <= 0) return res.status(400).json({ error: 'Donate at least 1 gold or gem.' });
        if (char.gold < gold) return res.status(400).json({ error: 'Not enough gold.' });
        if (char.gems < gems) return res.status(400).json({ error: 'Not enough gems.' });
        const now = Math.floor(Date.now() / 1000);
        await dbRun(db, 'UPDATE characters SET gold=gold-?, gems=gems-? WHERE id=?', [gold, gems, char.id]);
        await dbRun(db, 'INSERT INTO squad_base_donations (squad_id, base_id, char_id, gold, gems, created_at) VALUES (?,?,?,?,?,?)',
            [membership.squad_id, baseId, char.id, gold, gems, now]);
        const donateResult = await dbRun(db, 'UPDATE squad_treasury SET gold=gold+?, gems=gems+? WHERE squad_id=?',
            [gold, gems, membership.squad_id]);
        if (!(donateResult?.rowsAffected ?? donateResult?.changes ?? 0)) {
            await dbRun(db, 'INSERT INTO squad_treasury (squad_id, gold, gems) VALUES (?,?,?)',
                [membership.squad_id, gold, gems]);
        }
        res.json({ success: true, donated: { gold, gems } });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post('/squads/bases/:baseId/upgrade', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id, role FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        if (!membership) return res.status(403).json({ error: 'You are not in a squad.' });
        if (membership.role === 'member') return res.status(403).json({ error: 'Only leaders, co-leaders and officers can upgrade.' });
        const baseId = Number(req.params.baseId);
        const base = await dbGet(db, 'SELECT * FROM clan_bases WHERE id=?', [baseId]);
        if (!base) return res.status(404).json({ error: 'Base not found.' });
        if (Number(base.owner_squad_id || 0) !== membership.squad_id) return res.status(403).json({ error: 'Your squad does not own this base.' });
        const cur = await dbGet(db, 'SELECT upgrade_level FROM squad_base_upgrades WHERE squad_id=? AND base_id=?', [membership.squad_id, baseId]);
        const curLevel = Number(cur?.upgrade_level || 0);
        const cost = calcBaseUpgradeCost(base.tier, curLevel);
        if (!cost) return res.status(400).json({ error: 'Base is at max level.' });
        const treasury = await dbGet(db, 'SELECT gold, gems FROM squad_treasury WHERE squad_id=?', [membership.squad_id]);
        const tresGold = Number(treasury?.gold || 0);
        const tresGems = Number(treasury?.gems || 0);
        if (tresGold < cost.gold) return res.status(400).json({ error: `Squad treasury needs ${cost.gold} gold (has ${tresGold}).` });
        if (tresGems < cost.gems) return res.status(400).json({ error: `Squad treasury needs ${cost.gems} gems (has ${tresGems}).` });
        await dbRun(db, 'UPDATE squad_treasury SET gold=gold-?, gems=gems-? WHERE squad_id=?', [cost.gold, cost.gems, membership.squad_id]);
        await dbRun(db, `INSERT INTO squad_base_upgrades (squad_id, base_id, upgrade_level) VALUES (?,?,?)
            ON CONFLICT(squad_id, base_id) DO UPDATE SET upgrade_level=excluded.upgrade_level`,
            [membership.squad_id, baseId, cost.next_level]);
        await dbRun(db, 'INSERT INTO messages (sender_id,receiver_id,subject,body) VALUES (?,?,?,?)',
            [char.id, char.id, '🏰 Base Upgraded', `Base "${base.name}" upgraded to level ${cost.next_level}!`]);
        res.json({ success: true, level: cost.next_level, cost });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.get('/squads/bases/:baseId', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        if (!membership) return res.status(403).json({ error: 'You are not in a squad.' });
        const baseId = Number(req.params.baseId);
        const base = await dbGet(db, 'SELECT cb.*, s.name AS owner_squad_name FROM clan_bases cb LEFT JOIN squads s ON s.id = cb.owner_squad_id WHERE cb.id=?', [baseId]);
        if (!base) return res.status(404).json({ error: 'Base not found.' });

        const isOwned = Number(base.owner_squad_id) === membership.squad_id;
        const isOccupied = base.owner_squad_id !== null && !isOwned;
        // Base actions (capture / attack / loot) are locked while the squad has an active war
        const inWar = await dbGet(db, "SELECT 1 FROM clan_wars WHERE (attacker_squad_id=? OR defender_squad_id=?) AND status IN ('preparation','attacking') LIMIT 1",
            [membership.squad_id, membership.squad_id]);
        const warLocked = !!inWar;
        // Is the base's owning squad currently at war? (their next resolution time)
        let ownerAtWar = false;
        let ownerWarResolvesAt = 0;
        if (base.owner_squad_id) {
            const ownerWar = await dbGet(db,
                "SELECT attack_ends_at FROM clan_wars WHERE (attacker_squad_id=? OR defender_squad_id=?) AND status IN ('preparation','attacking') ORDER BY attack_ends_at ASC LIMIT 1",
                [base.owner_squad_id, base.owner_squad_id]);
            if (ownerWar) {
                ownerAtWar = true;
                ownerWarResolvesAt = Number(ownerWar.attack_ends_at || 0) * 1000;
            }
        }
        // Can attack? Must be occupied by another squad, user is officer+, no active war for this base, and 24h cooldown passed
        let canAttack = false;
        if (isOccupied && !warLocked && !ownerAtWar) {
            const officerCheck = await dbGet(db, "SELECT 1 FROM squad_members WHERE char_id=? AND role IN ('leader','co_leader','officer') LIMIT 1", [char.id]);
            if (officerCheck) {
                const activeWar = await dbGet(db, "SELECT 1 FROM clan_wars WHERE (attacker_squad_id=? OR defender_squad_id=?) AND status='preparation' AND base_id=? LIMIT 1",
                    [membership.squad_id, membership.squad_id, baseId]);
                if (!activeWar) {
                    const cooldown = await dbGet(db, "SELECT 1 FROM clan_wars WHERE attacker_squad_id=? AND created_at > ? LIMIT 1",
                        [membership.squad_id, Math.floor(Date.now() / 1000) - 86400]);
                    // Defender 24h protection after defending a war
                    const defProtected = await dbGet(db,
                        "SELECT 1 FROM clan_wars WHERE defender_squad_id=? AND status='completed' AND resolved_at > ? LIMIT 1",
                        [base.owner_squad_id, Math.floor(Date.now() / 1000) - 86400]);
                    if (!cooldown && !defProtected) canAttack = true;
                }
            }
        }

        // Defender 24h protection after defending a war — expose when this base can be attacked again
        let defenderProtectedUntil = 0;
        let lastDefendedAt = 0;
        if (isOccupied && base.owner_squad_id) {
            const defLast = await dbGet(db,
                "SELECT resolved_at FROM clan_wars WHERE defender_squad_id=? AND status='completed' AND resolved_at > ? ORDER BY resolved_at DESC LIMIT 1",
                [base.owner_squad_id, Math.floor(Date.now() / 1000) - 86400]);
            if (defLast && Number(defLast.resolved_at || 0) > 0) {
                lastDefendedAt = Number(defLast.resolved_at);
                defenderProtectedUntil = (lastDefendedAt + 86400) * 1000;
            }
        }

        res.json({
            base: {
                id: Number(base.id), name: base.name, tier: base.tier,
                map_x: Number(base.map_x), map_y: Number(base.map_y),
                owner_squad_id: Number(base.owner_squad_id || 0), owner_squad_name: base.owner_squad_name,
                is_owned: isOwned, is_occupied: isOccupied,
                can_capture: !base.owner_squad_id && !warLocked,
                can_loot: false,
                can_attack: canAttack,
                owner_at_war: ownerAtWar,
                owner_war_resolves_at: ownerWarResolvesAt,
                last_defended_at: lastDefendedAt,
                defender_protected_until: defenderProtectedUntil,
            }
        });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post('/squads/bases/:baseId/capture', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId);
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, "SELECT squad_id, role FROM squad_members WHERE char_id=? AND role IN ('leader','co_leader','officer') LIMIT 1", [char.id]);
        if (!membership) return res.status(403).json({ error: 'Only leaders, co-leaders and officers can capture bases.' });
        const baseId = Number(req.params.baseId);
        const base = await dbGet(db, 'SELECT * FROM clan_bases WHERE id=?', [baseId]);
        if (!base) return res.status(404).json({ error: 'Base not found.' });
        if (base.owner_squad_id) return res.status(400).json({ error: 'Base is already occupied.' });
        const cfg = NPC_BASE_CAPTURE[base.tier];
        if (!cfg) return res.status(400).json({ error: 'Invalid base tier.' });
        // Check member count
        const memberCount = await dbGet(db, 'SELECT COUNT(*) AS c FROM squad_members WHERE squad_id=?', [membership.squad_id]);
        if (Number(memberCount?.c || 0) < cfg.min_members) {
            return res.status(400).json({ error: `Need at least ${cfg.min_members} squad members to capture a ${base.tier} base (current: ${memberCount?.c || 0}).` });
        }
        // Check for existing war
        const activeWar = await dbGet(db, "SELECT 1 FROM clan_wars WHERE (attacker_squad_id=? OR defender_squad_id=?) AND status IN ('preparation','attacking') LIMIT 1",
            [membership.squad_id, membership.squad_id]);
        if (activeWar) return res.status(400).json({ error: 'Your squad already has an active war. Finish it before starting another.' });
        const now = Math.floor(Date.now() / 1000);
        const attackEndsAt = now + 43200; // 12h assignment phase
        const warIns = await dbRun(db, `INSERT INTO clan_wars (attacker_squad_id, defender_squad_id, base_id, status, phase, created_at, attack_ends_at, is_npc_war, defender_npc_count)
            VALUES (?,?,?,?,?,?,?,?,?)`,
            [membership.squad_id, 0, baseId, 'preparation', 'attacking', now, attackEndsAt, 1, cfg.npc_count]);
        const warId = Number(warIns.lastInsertRowid || 0);
        // Create outposts with NPC defenders
        const npcsPerOutpost = Math.ceil(cfg.npc_count / 5);
        const npcPower = calcNpcPower(cfg.npc_level);
        for (let i = 0; i < 5; i++) {
            const defPower = npcsPerOutpost * npcPower;
            await dbRun(db, 'INSERT INTO clan_war_outposts (war_id, outpost_index, attacker_power, defender_power) VALUES (?,?,0,?)', [warId, i, defPower]);
        }
        // Notify all squad members
        const squad = await dbGet(db, 'SELECT name FROM squads WHERE id=?', [membership.squad_id]);
        const squadName = squad?.name || 'Unknown';
        await notifySquadMembersAboutWar(db, membership.squad_id, warId,
            '⚔️ NPC Base Capture',
            `Your squad (${squadName}) has started capturing "${base.name}"! Assign members to outposts in the war panel.`);
        res.json({ success: true, war_id: warId, npc_count: cfg.npc_count, npc_level: cfg.npc_level, npc_power: npcPower });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post('/squads/bases/:baseId/pay-upkeep', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });
        const membership = await dbGet(db, 'SELECT squad_id, role FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        if (!membership) return res.status(403).json({ error: 'You are not in a squad.' });
        if (membership.role === 'member') return res.status(403).json({ error: 'Only leaders, co-leaders and officers can pay upkeep.' });
        const baseId = Number(req.params.baseId);
        const base = await dbGet(db, 'SELECT * FROM clan_bases WHERE id=?', [baseId]);
        if (!base) return res.status(404).json({ error: 'Base not found.' });
        if (Number(base.owner_squad_id || 0) !== membership.squad_id) return res.status(403).json({ error: 'Your squad does not own this base.' });
        const cur = await dbGet(db, 'SELECT upgrade_level, last_upkeep_paid FROM squad_base_upgrades WHERE squad_id=? AND base_id=?', [membership.squad_id, baseId]);
        const curLevel = Number(cur?.upgrade_level || 0);
        if (curLevel <= 0) return res.status(400).json({ error: 'Base has no upgrades yet.' });
        const totalLevel = await getSquadTotalLevel(db, membership.squad_id);
        const upkeepCost = calcBaseUpkeep(base.tier, curLevel, totalLevel);
        if (upkeepCost <= 0) return res.status(400).json({ error: 'No upkeep required.' });
        const treasury = await dbGet(db, 'SELECT gold FROM squad_treasury WHERE squad_id=?', [membership.squad_id]);
        if (Number(treasury?.gold || 0) < upkeepCost) return res.status(400).json({ error: `Treasury needs ${upkeepCost} gold for upkeep.` });
        const now = Math.floor(Date.now() / 1000);
        // Snap to 00:00 UTC today so expiry always aligns to midnight
        const paidAt = Math.floor(now / 86400) * 86400;
        await dbRun(db, 'UPDATE squad_treasury SET gold=gold-? WHERE squad_id=?', [upkeepCost, membership.squad_id]);
        await dbRun(db, 'UPDATE squad_base_upgrades SET last_upkeep_paid=?, upkeep_paid_by=? WHERE squad_id=? AND base_id=?',
            [paidAt, char.id, membership.squad_id, baseId]);
        res.json({ success: true, upkeep_paid: upkeepCost, valid_until: paidAt + 86400 });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

