// ── Mission UI Tick (bot protection) ─────────────────────────────────
// Client sends this when player interacts with mission UI buttons.
// The server checks for a recent tick before allowing /missions/start.
const _missionUiTicks = new Map();
const _missionNoTickStarts = new Map(); // char_name → count

router.post('/missions/ui-tick', auth, (req, res) => {
    _missionUiTicks.set(req.user.userId, Math.floor(Date.now() / 1000));
    res.json({ success: true });
});

// ── Missions Start ─────────────────────────────────────────────────────
router.post('/missions/start', auth, async (req, res) => {
    const userId = req.user.userId;
    if (_missionStartLock.has(userId)) {
        return res.status(400).json({ error: 'Mission start already in progress.' });
    }
    _missionStartLock.add(userId);
    try {
        const db = await getDb();
        const now = Math.floor(Date.now() / 1000);
        const { zoneId, spotId, missionIdx, size: reqSize } = req.body;
        const character = await getCurrentCharacter(db, userId);
        if (!character) return res.status(404).json({ error: 'Character not found' });

        // Anti-bot: check for UI tick within the last 60 seconds
        const lastTick = _missionUiTicks.get(userId) || 0;
        const hadTick = (now - lastTick) < 60;
        if (!hadTick && character.name) {
            _missionNoTickStarts.set(character.name, (_missionNoTickStarts.get(character.name) || 0) + 1);
        }
        const activeTraining = await dbGet(db, 'SELECT * FROM skill_training WHERE char_id = ? AND ends_at > ?',
            [character.id, now]);
        if (activeTraining) {
            return res.status(400).json({ error: 'Cannot start missions while training skills. Complete or cancel training first.' });
        }

        // Backend-enforced PvP cooldown: prevents bypassing the client overlay.
        const pvpCooldown = eventHas('discount_duels') ? 120 : 600;
        const activePrem = getActivePremium(character);
        const effectivePvpCooldown = hasPremium(activePrem, 'fortune_hunter') ? Math.floor(pvpCooldown * 0.50) : pvpCooldown;
        const lastBattleAt = Number(character.last_battle_at || 0);
        if (lastBattleAt + effectivePvpCooldown > now) {
            const secs = (lastBattleAt + effectivePvpCooldown) - now;
            return res.status(400).json({ error: `Wait ${secs < 60 ? secs + 's' : Math.ceil(secs / 60) + 'm'} before starting a mission.` });
        }

        const currentMap = character.current_map || 'overworld';
        let zone;

        if (currentMap === 'abyss') {
            zone = ABYSS_ZONES[zoneId];
        } else {
            zone = ZONES[zoneId];
        }

        if (!zone) return res.status(404).json({ error: 'Zone not found' });

        const spot = zone.spots.find(s => s.id === spotId);
        if (!spot) return res.status(404).json({ error: 'Spot not found' });

// Tutorial Lock Check: Wins < 4 only allows Easy (unless skipped)
        const isTutorial = isTutorialCharacter(character);
        if (isTutorial && (spot.difficulty === 'medium' || spot.difficulty === 'hard')) {
            return res.status(403).json({ error: 'Tutorial: You must complete 4 battles before attempting Medium or Hard missions.' });
        }

// Only small missions for tutorial (first 4 wins)
        if (isTutorial && reqSize && reqSize !== 'small') {
            return res.status(403).json({ error: 'Tutorial: Only Small missions are available until you win 4 battles.' });
        }

        const sizeKey = isTutorial ? 'small' : (['small', 'medium', 'large'].includes(reqSize) ? reqSize : 'small');
        const sizeConf = MISSION_SIZES[sizeKey];

        const todayStart = Math.floor(now / 86400) * 86400;
        const lastReset = character.daily_mp_reset_at || 0;
        let dailyMpSpent = character.daily_mp_spent || 0;

        if (lastReset < todayStart) {
            dailyMpSpent = 0;
            await dbRun(db, 'UPDATE characters SET daily_mp_spent=0, daily_mp_reset_at=? WHERE id=?', [todayStart, character.id]);
        }

        await applyMpRegen(db, character.id);
        const freshChar = await dbGet(db, 'SELECT * FROM characters WHERE id=?', [character.id]);
        const currentMp = freshChar.mission_points ?? 0;

        const difficulty = spot.difficulty;
        const [minGold, maxGold] = zone.payoutBase[difficulty];

        let minXp = 0, maxXp = 0;
        if (sizeKey === 'small') {
            minXp = 0;
            maxXp = 6;
        } else if (sizeKey === 'medium') {
            minXp = 0;
            maxXp = 9;
        } else {
            minXp = 0;
            maxXp = 12;
        }

        let xpReward = Math.floor(Math.random() * (maxXp - minXp + 1)) + minXp;
        xpReward = Math.max(0, xpReward);

        const baseGoldRoll = (Math.floor(Math.random() * (maxGold - minGold + 1)) + minGold);
        const goldReward = Math.floor(baseGoldRoll * MISSION_BASE_GOLD_MULT * sizeConf.rewardMult);

        const missionList = spot.missions.map(m => typeof m === 'string' ? m : m.name);
        const missionName = (missionIdx !== undefined && missionList[missionIdx]) ? missionList[missionIdx] : missionList[Math.floor(Math.random() * missionList.length)];

        const baseDuration = sizeConf.duration;
        let duration = eventHas('short_missions') ? Math.max(30, Math.floor(baseDuration / 2)) : baseDuration;
        if (hasPremium(activePrem, 'fortune_hunter')) duration = Math.max(30, Math.floor(duration * 0.50));

        // Tutorial force duration
        if (isTutorial) duration = 10;

        let effectiveMpCost = sizeConf.mpCost;
        const midasFlow = PREMIUM_SYNERGIES.find(s => s.requires.includes('arcane_reservoir') && s.requires.includes('fortune_hunter'));
        if (midasFlow && hasPremium(activePrem, 'arcane_reservoir') && hasPremium(activePrem, 'fortune_hunter')) {
            effectiveMpCost = Math.max(0, effectiveMpCost - midasFlow.effect.mp_cost_reduction);
        }

        if (!isTutorial && currentMp < effectiveMpCost) {
            return res.status(400).json({ error: `Not enough MP. ${sizeConf.label} mission costs ${effectiveMpCost} MP, you have ${currentMp}.` });
        }

        const insertResult = await dbRun(db, `
    INSERT INTO active_missions (character_id, zone, spot, spot_name, mission_name, difficulty, gold_reward, xp_reward, started_at, ends_at, map_type, size)
    SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?
    WHERE NOT EXISTS (SELECT 1 FROM active_missions WHERE character_id = ?)
`, [character.id, zoneId, spotId, spot.name, missionName, difficulty, goldReward, xpReward, now, now + duration, currentMap, sizeKey, character.id]);

        const didInsert = insertResult.rowsAffected ?? insertResult.changes ?? 0;
        if (!didInsert) return res.status(400).json({ error: 'You already have an active mission.' });

        if (!isTutorial) {
            await dbRun(db, 'UPDATE characters SET mission_points=mission_points-?, daily_mp_spent=daily_mp_spent+? WHERE id=?',
                [effectiveMpCost, effectiveMpCost, character.id]);
            await recordTotalMpSpent(db, character.id, effectiveMpCost);
        }

        // Mark mission_log as succeeded (handled by api_log middleware)
        res.json({
            success: true,
            mission: {
                id: Number(insertResult.lastInsertRowid),
                zone: zoneId,
                spot: spotId,
                spot_name: spot.name,
                mission_name: missionName,
                missionName,
                difficulty,
                size: sizeKey,
                gold_reward: goldReward,
                xp_reward: xpReward,
                started_at: now,
                ends_at: now + duration,
                duration,
                map_type: currentMap
            }
        });
    } catch (e) {
        console.error('Mission start error:', e);
        res.status(500).json({ error: e?.message || String(e) });
    } finally {
        _missionStartLock.delete(userId);
    }
});

// ── Missions Collect (UPDATED with skill tree passive bonuses) ────────────
async function collectMissionForCharacter(db, characterId) {
    try {
        const character = await dbGet(db, 'SELECT * FROM characters WHERE id=?', [characterId]);
        if (!character) return { __error: 'Character not found', __status: 404 };
        await applyMpRegen(db, character.id);
        await applyHpRegen(db, character.id);
        const freshChar = await dbGet(db, 'SELECT * FROM characters WHERE id = ?', [character.id]);
        const mission = await dbGet(db, 'SELECT * FROM active_missions WHERE character_id = ?', [character.id]);
        if (!mission) return { __error: 'No active mission', __status: 400 };
        let zoneLevel = 1;
        if (mission.map_type === 'abyss') {
            const zone = ABYSS_ZONES[mission.zone];
            zoneLevel = zone?.minLevel || 39;
        } else {
            const zone = ZONES[mission.zone];
            zoneLevel = zone?.minLevel || 1;
        }
        const now = Math.floor(Date.now() / 1000);
        if (now < mission.ends_at) return { __error: 'Mission not yet complete', __status: 400 };
        let playerStats = null;
        if (mission.difficulty === 'nightmare' || mission.map_type === 'abyss') {
            const glvl = (freshChar.level || 1);
            const r = () => 0.85 + Math.random() * 0.30;
            const gearStr  = Math.floor((10 + glvl * 0.8) * r());
            const gearAgi  = Math.floor((10 + glvl * 0.8) * r());
            const gearMag  = Math.floor((10 + glvl * 0.8) * r());
            const gearDef  = Math.floor((15 + glvl * 2.0) * r());
            const gearArmor = Math.floor((30 + glvl * 3.5) * r());
            const gearVit  = Math.floor((8 + glvl * 0.8) * r());
            const gearHit  = Math.floor((8 + glvl * 0.5) * r());
            const gearCrit = Math.floor((8 + glvl * 0.5) * r());
            const gearHp   = Math.floor((50 + glvl * 4.0) * r());
            const gearDmgMin = Math.floor((10 + glvl * 2.0) * r());
            const gearDmgMax = Math.floor((20 + glvl * 4.0) * r());

            const baseStr  = Number(freshChar.strength || 0);
            const baseAgi  = Number(freshChar.agility || 0);
            const baseMag  = Number(freshChar.magic || 0);
            const baseDef  = Number(freshChar.defense || 0);
            const baseVit  = Number(freshChar.vitality || 10);
            const baseHit  = Number(freshChar.hit_chance || 0);
            const baseCrit = Number(freshChar.crit_chance || 3);

            const totalStr  = baseStr + gearStr;
            const totalAgi  = baseAgi + gearAgi;
            const totalMag  = baseMag + gearMag;
            const totalDef  = baseDef + gearDef;
            const totalVit  = baseVit + gearVit;
            const totalHit  = baseHit + gearHit;
            const totalCrit = baseCrit + gearCrit;

            const baseHpMax = 50 + baseVit * 25 + baseDef * 2;
            const totalHpMax = baseHpMax + gearVit * 25 + gearHp;
            const baseDmgMin = 5 + Math.floor(baseStr * 0.5);
            const baseDmgMax = 15 + Math.floor(baseStr * 1.2);
            const totalDmgMin = baseDmgMin + gearDmgMin;
            const totalDmgMax = baseDmgMax + gearDmgMax;

            const elem_dmg = { pyro: 0, water: 0, wind: 0, electro: 0 };
            const elem_resist = { pyro: 0, water: 0, wind: 0, electro: 0 };
            for (const el of ['pyro', 'water', 'wind', 'electro']) {
                elem_dmg[el] = 20 + Math.floor(Math.random() * 181);
                elem_resist[el] = 100 + Math.floor(Math.random() * 201);
            }

            playerStats = {
                hpMax: totalHpMax,
                hp_max: totalHpMax,
                strength: totalStr,
                agility: totalAgi,
                magic: totalMag,
                defense: totalDef,
                vitality: totalVit,
                hit_chance: totalHit,
                hitChance: totalHit,
                crit_chance: totalCrit,
                critChance: totalCrit,
                dmgMin: totalDmgMin,
                dmg_min: totalDmgMin,
                dmgMax: totalDmgMax,
                dmg_max: totalDmgMax,
                armor: gearArmor,
                elem_dmg,
                elem_resist,
            };
        }
        const isEvent = eventHas('grand_festival');
        const activePremCollect = getActivePremium(freshChar);
        const hasUlt = hasUltimate(activePremCollect);
const equippedArray = await getEquippedItemsArray(db, freshChar.id);
        const hpMax = calcHpMax(freshChar, equippedArray) + await beastHpBonus(db, freshChar.id);
        const hpCurrent = freshChar.hp_current ?? hpMax;
        const _beastStats = await beastStatBonus(db, freshChar.id);
        const tempDef = Number(JSON.parse(freshChar.temp_stat_buffs || '{}')?.defense?.exp > now ? JSON.parse(freshChar.temp_stat_buffs || '{}').defense.value || 0 : 0);
        const setBonuses = getEquippedSetBonuses(equippedArray);
        const { dmgMin, dmgMax } = calcBaseDamage(freshChar, equippedArray);
        const charActiveSkills = getActiveSkills(freshChar);

        // ── Skill tree passive bonuses ──────────────────────────────────────
        const learnedRows = await dbAll(db, 'SELECT skill_id FROM character_skill_tree WHERE char_id=?', [freshChar.id]);
        const learnedIds = learnedRows.map(r => r.skill_id);
        const skillPassives = await computePassiveBonusesWithProgress(db, freshChar.class, learnedIds, freshChar.id);
        const skillActives  = await computeActiveCombatEffectsWithProgress(db, freshChar.class, learnedIds, freshChar.id);
        const skillMods     = await computeClassModifiersWithProgress(db, freshChar.class, learnedIds, freshChar.id);

        // Rogue no-shield agility bonus
        let noShieldAgiBonus = 0;
        if (freshChar.class === 'rogue') {
            const equipped = await getEquippedItems(db, freshChar.id);
            const hasShield = !!equipped.shield;
            const shieldIsOffhand = hasShield && equipped.shield.rogueOffhand === true;
            if (!hasShield || shieldIsOffhand) {
                noShieldAgiBonus = Math.floor((freshChar.agility || 0) * 0.05);
            }
        }
        const playerWeapon = getEquippedWeaponData(equippedArray);
        const playerShield = getEquippedShieldData(equippedArray);
        const playerFighter = {
            id: freshChar.id,
            name: freshChar.name,
            class: freshChar.class,
            level: freshChar.level,
            weapon: playerWeapon,
            shield: playerShield,
            hp: hpCurrent,
            hpMax: hpMax + (skillPassiveBonus(freshChar.vitality || 0, skillPassives.vitality) * 25),
            dmgMin: dmgMin + skillPassiveBonus(dmgMin, skillPassives.dmg_min),
            dmgMax: dmgMax + skillPassiveBonus(dmgMax, skillPassives.dmg_max),
            strength: (freshChar.strength || 0) + (setBonuses.strength || 0) + skillPassiveBonus(freshChar.strength || 0, skillPassives.strength) + getEquippedStatTotal(equippedArray, 'strength') + _beastStats.str,
            agility: (freshChar.agility || 0) + (setBonuses.agility || 0) + skillPassiveBonus(freshChar.agility || 0, skillPassives.agility) + noShieldAgiBonus + getEquippedStatTotal(equippedArray, 'agility'),
            magic: (freshChar.magic || 0) + (setBonuses.magic || 0) + skillPassiveBonus(freshChar.magic || 0, skillPassives.magic) + getEquippedStatTotal(equippedArray, 'magic') + _beastStats.mag,
            defense: (freshChar.defense || 0) + (setBonuses.defense || 0) + skillPassiveBonus(freshChar.defense || 0, skillPassives.defense) + getEquippedStatTotal(equippedArray, 'defense') + _beastStats.def,
            hit_chance: (freshChar.hit_chance || 0) + (setBonuses.hit_chance || 0) + skillPassiveBonus(freshChar.hit_chance || 0, skillPassives.hit_chance) + getEquippedStatTotal(equippedArray, 'hit_chance'),
            crit_chance: (freshChar.crit_chance || 0) + (setBonuses.crit_chance || 0) + skillPassiveBonus(freshChar.crit_chance || 0, skillPassives.crit_chance) + getEquippedStatTotal(equippedArray, 'crit_chance'),
            armor: calcArmorValue(freshChar, equippedArray, _beastStats.def + tempDef) + skillPassiveBonus(calcArmorValue(freshChar, equippedArray, _beastStats.def + tempDef), skillPassives.armor),
            elem_dmg: {
                pyro:    (calcElemDmg(equippedArray).pyro    || 0) + (skillPassives.pyro_dmg    || 0),
                water:   (calcElemDmg(equippedArray).water   || 0) + (skillPassives.water_dmg   || 0),
                wind:    (calcElemDmg(equippedArray).wind    || 0) + (skillPassives.wind_dmg    || 0),
                electro: (calcElemDmg(equippedArray).electro || 0) + (skillPassives.electro_dmg || 0),
            },
            elem_resist: {
                pyro:    (calcElemResist(freshChar, equippedArray).pyro    || 0) + (skillPassives.pyro_resist    || 0),
                water:   (calcElemResist(freshChar, equippedArray).water   || 0) + (skillPassives.water_resist   || 0),
                wind:    (calcElemResist(freshChar, equippedArray).wind    || 0) + (skillPassives.wind_resist    || 0),
                electro: (calcElemResist(freshChar, equippedArray).electro || 0) + (skillPassives.electro_resist || 0),
            },
            skillEffects: skillActives,
            skillMods: skillMods,
            baseActiveSkills: charActiveSkills,
            activeSkills: mergeActiveSkills(charActiveSkills, skillActives),
            attackZones: JSON.parse(freshChar.attack_zones || 'null') || DEFAULT_ATTACK_ZONES,
            blockZones: JSON.parse(freshChar.block_zones || 'null') || DEFAULT_BLOCK_ZONES,
            dualWield: freshChar.class === 'rogue' && rogueHasDualWield(learnedIds),
            blockEffectiveness: skillPassives.block_effectiveness || 0,
        };

        // Attach elemental companion for missions
        const missionElemRow = await dbGet(db, 'SELECT * FROM elementals WHERE char_id = ? AND is_equipped = 1', [freshChar.id]);
        if (missionElemRow) {
            const elemStats = calcElemStats(missionElemRow);
            playerFighter._elementalFighter = {
                ...missionElemRow,
                ...elemStats,
                hp: missionElemRow.hp_current ?? elemStats.hpMax
            };
        }

        applyWeaponSkill(playerFighter);

        const isTutorial = isTutorialCharacter(freshChar);

        // Build NPC and override its name with the mission name
        // If a player is underleveled for a zone, missions should still scale to the zone's minimum level.
        const missionEffectiveLevel = Math.max(Number(freshChar.level || 1), Number(zoneLevel || 1));
        const npc = buildNpc(mission.difficulty, missionEffectiveLevel, zoneLevel, mission.map_type === 'abyss' && playerStats ? playerStats : playerFighter);
        const npcName = getNPCNameFromMission(mission.mission_name);
        npc.name = npcName;
        npc.class = 'npc';  // Add class for mage penalty check (not a mage)

        // Zone-based stat overrides — hard = gatekeeper level, medium = 75%, easy = 50%
        if (mission.zone === 'mountains') {
            if (mission.difficulty === 'hard') {
                npc.magic = 80; npc.crit_chance = 70; npc.armor = 46;
            } else if (mission.difficulty === 'medium') {
                npc.magic = 60; npc.crit_chance = 52; npc.armor = 34;
            } else if (mission.difficulty === 'easy') {
                npc.magic = 40; npc.crit_chance = 35; npc.armor = 23;
            }
        } else if (mission.zone === 'ruins') {
            if (mission.difficulty === 'hard') {
                npc.dmgMin = 120; npc.dmgMax = 160; npc.agility = 120;
                npc.magic = 150; npc.crit_chance = 120; npc.armor = 120;
            } else if (mission.difficulty === 'medium') {
                npc.dmgMin = 90; npc.dmgMax = 120; npc.agility = 90;
                npc.magic = 112; npc.crit_chance = 90; npc.armor = 90;
            } else if (mission.difficulty === 'easy') {
                npc.dmgMin = 60; npc.dmgMax = 80; npc.agility = 60;
                npc.magic = 75; npc.crit_chance = 60; npc.armor = 60;
            }
        } else if (mission.zone === 'dark_city') {
            if (mission.difficulty === 'hard') {
                npc.agility = 200; npc.magic = 500; npc.crit_chance = 250; npc.armor = 200;
            } else if (mission.difficulty === 'medium') {
                npc.agility = 150; npc.magic = 375; npc.crit_chance = 187; npc.armor = 150;
            } else if (mission.difficulty === 'easy') {
                npc.agility = 100; npc.magic = 250; npc.crit_chance = 125; npc.armor = 100;
            }
        }

        // Warrior class: deduct flat +1 dmg per 10 STR from NPC so the bonus actually helps
        if (freshChar.class === 'warrior') {
            const strBonus = Math.floor((freshChar.strength || 0) / 10);
            if (strBonus > 0) {
                npc.dmgMin = Math.max(1, npc.dmgMin - strBonus);
                npc.dmgMax = Math.max(npc.dmgMin + 1, npc.dmgMax - strBonus);
            }
        }

        // Stat variance pass — different ranges per stat for better variety
        // HP stays close to base, hit/crit can vary widely, others moderate
        if (mission.map_type !== 'abyss') {
            const ranges = {
                hp:         [0.9, 1.4],
                dmgMin:     [0.7, 1.3],
                dmgMax:     [0.7, 1.3],
                agility:    [0.7, 1.3],
                magic:      [0.7, 1.3],
                hit_chance: [0.9, 4.0],
                crit_chance:[0.5, 3.5],
                armor:      [0.5, 2.5],
                vitality:   [0.7, 1.3],
            };
            for (const [k, [lo, hi]] of Object.entries(ranges)) {
                const mult = lo + Math.random() * (hi - lo);
                let val = Math.floor((npc[k] || 0) * mult);
                if (k === 'hp') { npc[k] = Math.max(10, val); npc.hpMax = npc.hp; }
                else if (k === 'dmgMin') npc[k] = Math.max(1, val);
                else if (k === 'dmgMax') npc[k] = Math.max(Math.max(2, (npc.dmgMin || 0) + 1), val);
                else if (k === 'agility' || k === 'vitality') npc[k] = Math.max(1, val);
                else if (k === 'hit_chance') npc[k] = Math.max(10, val);
                else if (k === 'crit_chance' || k === 'magic' || k === 'armor') npc[k] = Math.max(0, val);
            }
        }

        // Random elemental resists for hard missions — at least 2 types, up to all 4, scales with zone
        // Skip for abyss missions — buildNpc() already scales from player's own gear resists
        if (mission.difficulty === 'hard' && mission.map_type !== 'abyss') {
            const allElem = ['pyro', 'water', 'wind', 'electro'];
            const count = Math.min(4, 2 + (Math.random() < 0.5 ? 1 : 0) + (Math.random() < 0.25 ? 1 : 0));
            const chosen = [...allElem].sort(() => Math.random() - 0.5).slice(0, count);
            const maxR = Math.min(100, Math.floor(20 + zoneLevel * 2.5));
            npc.elem_resist = { pyro: 0, water: 0, wind: 0, electro: 0 };
            for (const el of chosen) npc.elem_resist[el] = Math.floor(Math.random() * maxR * 0.7) + Math.floor(maxR * 0.3);
        }

        // Force win for new characters (first 4 battles)
        let forceWinnerId = null;
        if (isTutorial) {
            forceWinnerId = freshChar.id;
        }

        const battleStats = {
            you: summarizeBattleStats(playerFighter),
            enemy: summarizeBattleStats(npc),
        };

        const battle = isTutorial
            ? createTutorialBattleResult(playerFighter, npc)
            : runBattle(playerFighter, npc, forceWinnerId);
        let playerWon = battle.winnerId === freshChar.id;
        const isDraw = battle.winnerId === 0;

        // Add tutorial note if we used forceWinnerId to flip a loss
        if (forceWinnerId && isTutorial) {
            if (!battle.log.some(line => line.includes('Tutorial victory'))) {
                battle.log.push('✨ Tutorial victory - experience gained!');
            }
        }

        await recordMissionSpotResult(db, {
            charId: freshChar.id,
            mapType: mission.map_type || 'overworld',
            zoneId: mission.zone,
            spotId: mission.spot,
            won: playerWon,
            now
        });
        if (playerWon) {
            await recordMonsterDefeat(db, {
                charId: freshChar.id,
                source: mission.map_type === 'abyss' ? 'abyss_mission' : 'mission',
                monsterKey: npcName,
                monsterName: npcName,
                count: 1,
                now
            });
            await recordEquipmentlessWins(db, freshChar, equippedArray);
            await grantWeaponXP(db, freshChar.id, WEAPON_XP_PER_MISSION);
        }

        let goldEarned;
        let xpEarned;
        if (isTutorial) {
            goldEarned = 250;
            xpEarned = 1;
        } else {
            goldEarned = playerWon ? mission.gold_reward : (isDraw ? Math.floor(mission.gold_reward * 0.50) : Math.floor(mission.gold_reward * 0.10));
            xpEarned = playerWon ? mission.xp_reward : (isDraw ? Math.floor(mission.xp_reward * 0.50) : 0);

            // Add damage-based bonus
            const sizeConf = MISSION_SIZES[mission.size || 'small'];
            const mpMultiplier = sizeConf.mpCost / 60;
            const damageDiff = Math.max(0, battle.totalDmgToB - battle.totalDmgToA);
            const damageGold = Math.floor(damageDiff * mpMultiplier);

            goldEarned += damageGold;

            // Level gold bonus: scales with character level and mission MP
            if (playerWon) {
                const lvl = freshChar.level || 1;
                const lvlMpMult = sizeConf.mpCost / 20;
                let lvlMin, lvlMax;
                if (mission.difficulty === 'nightmare') { lvlMin = 80; lvlMax = 100; }
                else if (mission.difficulty === 'hard') { lvlMin = 60; lvlMax = 80; }
                else { lvlMin = 40; lvlMax = 60; }
                const per20Mp = lvlMin + Math.floor(Math.random() * (lvlMax - lvlMin + 1));
                goldEarned += Math.floor(per20Mp * lvlMpMult * lvl);
            }

            if (isEvent) {
                goldEarned *= 2;
                xpEarned *= 2;
            }
            if (hasPremium(activePremCollect, 'fortune_hunter')) {
                goldEarned = Math.floor(goldEarned * 1.30);
            }
            if (hasUlt) {
                xpEarned = Math.floor(xpEarned * 1.50);
            }
        }

        const gemChance = isTutorial ? 0 : (isEvent ? 0.15 : 0.05);
        let gemsFound = 0;
        if (playerWon && Math.random() < gemChance) gemsFound = 1;

        // Tutorial Check: Don't deplete HP for the first 4 battles
        const newHp = isTutorial ? (freshChar.hp_current ?? playerFighter.hpMax) : Math.max(0, battle.hpRemainingA);

        let newXp = (freshChar.xp || 0) + xpEarned, newLevel = freshChar.level, leveledUp = false;
        while (newXp >= LEVEL_XP(newLevel)) { newXp -= LEVEL_XP(newLevel); newLevel++; leveledUp = true; }
        let newWins = freshChar.wins + (playerWon ? 1 : 0);
        let newLosses = freshChar.losses + (playerWon ? 0 : (isDraw ? 0 : 1));
        let newDraws = freshChar.draws + (isDraw ? 1 : 0);

        let tutorialMessage = null;
        if (isTutorial && newWins === 4) {
            tutorialMessage = "✨ Tutorial complete! Your character is now ready for the real challenge. Note: Further missions will now affect your HP. Check the 'Upgrade' tab to build your stats, the 'Shop' to buy items, and your 'Inventory' to manage your gear!";
        }

        // Handle level up: reset HP to full and give loot box
        let levelUpMessage = null;
        let finalHp = newHp;
        if (leveledUp) {
            const equippedArray = await getEquippedItemsArray(db, freshChar.id);
            const newCharWithLevel = { ...freshChar, level: newLevel };
            const newHpMax = calcHpMax(newCharWithLevel, equippedArray);
            finalHp = newHpMax;

            // Give a common loot box for leveling up
            const lootBox = LOOT_BOXES.find(box => box.id === 'lootbox_common');
            if (lootBox) {
                await addStackableInventoryItem(db, freshChar.id, 'consumable', lootBox, 1);
            }
            levelUpMessage = `🎉 Level Up! You reached level ${newLevel}! HP restored to full and you received a Common Loot Box!`;
        }

        const missionClaimResult = await dbRun(
            db,
            'DELETE FROM active_missions WHERE character_id = ? AND started_at = ? AND ends_at = ?',
            [freshChar.id, mission.started_at, mission.ends_at]
        );
        const claimedMission = missionClaimResult?.rowsAffected ?? missionClaimResult?.changes ?? 0;
        if (!claimedMission) {
            return { __error: 'Mission rewards already collected.', __status: 409 };
        }

        await dbRun(db, `UPDATE characters SET xp=?,gold=gold+?,gems=gems+?,level=?,wins=?,losses=?,draws=draws+?,hp_current=?,total_gold_earned=total_gold_earned+?,total_gems_earned=COALESCE(total_gems_earned, 0)+?,mission_gems_earned=COALESCE(mission_gems_earned, 0)+?,damage_dealt=damage_dealt+?,top_damage_dealt=MAX(top_damage_dealt, ?),damage_negated_phys=damage_negated_phys+?,damage_negated_elem=damage_negated_elem+?,damage_negated_shield=damage_negated_shield+? WHERE id=?`,
            [newXp, goldEarned, gemsFound, newLevel, newWins, newLosses, isDraw ? 1 : 0, finalHp, goldEarned, gemsFound, gemsFound, battle.totalDmgToB || 0, battle.totalDmgToB || 0, battle.totalAbsorbedPhysA || 0, battle.totalAbsorbedElemA || 0, battle.totalAbsorbedShieldA || 0, freshChar.id]);
        const weekStart = getCurrentWeekStart();
        await incrementWeeklyPerformance(db, freshChar.id, battle.totalDmgToB || 0, playerWon, weekStart);
        await handleReferralLevelMilestone(db, freshChar.user_id, freshChar.level, newLevel);

        // ── Skill tree stat tracking ───────────────────────────────────────
        if (playerWon && mission.difficulty === 'hard') {
            await dbRun(db, 'UPDATE characters SET hard_missions_completed = hard_missions_completed + 1 WHERE id=?', [freshChar.id]);
        }
        if (playerWon && mission.difficulty === 'nightmare') {
            await dbRun(db, 'UPDATE characters SET nightmare_missions_completed = nightmare_missions_completed + 1 WHERE id=?', [freshChar.id]);
        }
        if (playerWon) {
            await dbRun(db, 'UPDATE characters SET total_missions_completed = total_missions_completed + 1 WHERE id=?', [freshChar.id]);
        }
        if (playerWon) {
            await recordDamageStyleWin(db, freshChar.id, battle.totalElemDmgDealtA || battle.totalElemDmgDealt || 0);
        }

        const drops = [];
        let matsByZone;
        if (mission.map_type === 'abyss') {
            matsByZone = {
                shadowfen: [
                    { id:'void_shard', emoji:'🔮', name:'Void Shard' },
                    { id:'shadow_essence', emoji:'🌑', name:'Shadow Essence' },
                    { id:'abyss_crystal', emoji:'💎', name:'Abyss Crystal' }
                ],
                crimson: [
                    { id:'crimson_crystal', emoji:'🔴', name:'Crimson Crystal' },
                    { id:'fire_essence', emoji:'🔥', name:'Fire Essence' },
                    { id:'infernal_core', emoji:'💀', name:'Infernal Core' }
                ],
                void: [
                    { id:'void_crystal', emoji:'🔮', name:'Void Crystal' },
                    { id:'null_essence', emoji:'🌑', name:'Null Essence' },
                    { id:'abyss_fragment', emoji:'🧩', name:'Abyss Fragment' }
                ],
                citadel: [
                    { id:'shadowsteel', emoji:'⚙️', name:'Shadowsteel' },
                    { id:'soul_essence', emoji:'👻', name:'Soul Essence' },
                    { id:'obsidian_shard', emoji:'🪨', name:'Obsidian Shard' }
                ],
                eternal_dark: [
                    { id:'dark_essence', emoji:'🌑', name:'Dark Essence' },
                    { id:'primordial_shard', emoji:'✨', name:'Primordial Shard' },
                    { id:'eternal_core', emoji:'💠', name:'Eternal Core' }
                ]
            };
        } else {
            matsByZone = {
                forest: [
                    { id:'wood', emoji:'🪵', name:'Wood' },
                    { id:'wolf_pelt', emoji:'🐺', name:'Wolf Pelt' },
                    { id:'herbs', emoji:'🌿', name:'Herbs' }
                ],
                swamp: [
                    { id:'iron_ore', emoji:'⛏️', name:'Iron Ore' },
                    { id:'poison_gland', emoji:'🐸', name:'Poison Gland' },
                    { id:'swamp_crystal', emoji:'💎', name:'Swamp Crystal' }
                ],
                mountains: [
                    { id:'mithril_ore', emoji:'✨', name:'Mithril Ore' },
                    { id:'frost_essence', emoji:'❄️', name:'Frost Essence' },
                    { id:'dragon_scale_shard', emoji:'🐉', name:'Dragon Scale Shard' }
                ],
                ruins: [
                    { id:'arcane_dust', emoji:'✨', name:'Arcane Dust' },
                    { id:'rune_fragment', emoji:'🔮', name:'Rune Fragment' },
                    { id:'void_shard', emoji:'🌑', name:'Void Shard' }
                ],
                dark_city: [
                    { id:'shadow_essence', emoji:'🌑', name:'Shadow Essence' },
                    { id:'demon_core', emoji:'👹', name:'Demon Core' }
                ],
            };
        }
        const mats = matsByZone[mission.zone] || (mission.map_type === 'abyss' ? matsByZone.shadowfen : matsByZone.forest);
        const addMaterialDrop = async (mat, qty) => {
            const existing = await dbGet(db, `SELECT * FROM inventory WHERE char_id=? AND item_type='raw_mat' AND json_extract(item_data,'$.id')=?`, [freshChar.id, mat.id]);
            const rarity = RAW_MATERIALS[mat.id]?.rarity || 'common';
            if (existing) {
                const d = JSON.parse(existing.item_data);
                d.qty = (d.qty || 1) + qty;
                if (!d.rarity) d.rarity = rarity;
                await dbRun(db, 'UPDATE inventory SET item_data=? WHERE id=?', [JSON.stringify(d), existing.id]);
            } else {
                await dbRun(db, `INSERT INTO inventory (char_id,item_type,item_data) VALUES (?,?,?)`, [freshChar.id, 'raw_mat', JSON.stringify({ ...mat, rarity, qty })]);
            }
            drops.push({ mat: mat.id, qty });
        };

        if (isTutorial && playerWon) {
            const tutorialDropCount = Math.min(2, mats.length);
            const tutorialPool = [...mats].sort(() => Math.random() - 0.5).slice(0, tutorialDropCount);
            for (const mat of tutorialPool) {
                await addMaterialDrop(mat, 1 + Math.floor(Math.random() * 2));
            }
        } else {
            const dropChance = playerWon ? 0.6 : (isDraw ? 0.4 : 0.2);
            for (const mat of mats) {
                if (Math.random() < dropChance) {
                    await addMaterialDrop(mat, 1 + Math.floor(Math.random() * 3));
                }
            }
        }

        // Zone-specific unique material drop (abyss only, difficulty-scaled rate)
        if (mission.map_type === 'abyss') {
            const zoneUniqueMats = {
                shadowfen:    { id:'fen_cursed_bone',    emoji:'🦴', name:'Fen Cursed Bone' },
                crimson:      { id:'crimson_royal_blood',emoji:'🩸', name:'Crimson Royal Blood' },
                void:         { id:'void_null_core',     emoji:'🖤', name:'Void Null Core' },
                citadel:      { id:'citadel_obsidian_heart', emoji:'💜', name:'Obsidian Heart' },
                eternal_dark: { id:'eternal_spark',      emoji:'✨', name:'Eternal Spark' },
            };
            const uniqueMat = zoneUniqueMats[mission.zone];
            if (uniqueMat) {
                const diffRates = { nightmare: 0.35, hard: 0.15, normal: 0.06 };
                const rate = diffRates[mission.difficulty] || 0;
                if (Math.random() < rate) {
                    await addMaterialDrop(uniqueMat, 1);
                }
            }
        }

        try {
            await dbRun(db, `INSERT INTO battles (
        attacker_id, defender_id, winner_id, attacker_name, defender_name, log, 
        fought_at, battle_type, xp_gained, gold_gained, total_dmg_dealt, total_dmg_taken
    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,
                [freshChar.id, -1, playerWon ? freshChar.id : (isDraw ? 0 : -1), freshChar.name, mission.mission_name,
                    JSON.stringify(battle.log), now, 'mission', xpEarned, goldEarned,
                    battle.totalDmgToB, battle.totalDmgToA]);
        } catch {}

        // Save elemental HP after mission
        if (playerFighter._elementalFighter) {
            await dbRun(db, 'UPDATE elementals SET hp_current=? WHERE char_id=? AND id=?',
                [battle.elementalHpA, freshChar.id, playerFighter._elementalFighter.id]);
        }

        try {
            const subject = playerWon ? `✅ Mission Report: ${mission.mission_name}` : (isDraw ? `🤝 Mission Draw: ${mission.mission_name}` : `💀 Mission Failed: ${mission.mission_name}`);
            const payload = JSON.stringify({
                log: battle.log,
                won: playerWon,
                goldEarned,
                xpEarned,
                type: 'mission',
                npcName: npcName,  // Use the extracted NPC name here
                npcLevel: missionEffectiveLevel,
                missionName: mission.mission_name,
                totalDmgDealt: battle.totalDmgToB,
                totalDmgTaken: battle.totalDmgToA,
                battleStats
            });
            await dbRun(db, 'INSERT INTO messages (sender_id,receiver_id,subject,body) VALUES (?,?,?,?)', [freshChar.id, freshChar.id, subject, `BATTLE_REPORT:${payload}`]);
        } catch {}

        // Auto-hide old mission reports if prune toggle is ON
        try {
            const userRow = await dbGet(db, 'SELECT inbox_prune_missions FROM users WHERE id = ?', [freshChar.user_id]);
            if (Number(userRow?.inbox_prune_missions ?? 1) !== 0) {
                await hideOldMissionReports(db, freshChar.id, 10);
            }
        } catch {}

        const updatedChar = await dbGet(db, 'SELECT * FROM characters WHERE id = ?', [freshChar.id]);
        return {
            success: true, won: playerWon, battleLog: battle.log,
            message: `${playerWon ? 'Victory' : (isDraw ? 'Draw' : 'Defeated')} — ${goldEarned} gold${gemsFound ? `, 💎 ${gemsFound} gem found!` : ''}, ${xpEarned} XP`,
            goldEarned, xpEarned, gemsFound, leveledUp, newLevel: leveledUp ? newLevel : undefined,
            levelUpMessage,
            drops, hpRemaining: finalHp,
            tutorialMessage,
            activeEvent: isEvent ? GLOBAL_EVENTS[0] : null,
            character: await buildCharacterResponse(updatedChar, db),
            totalDmgDealt: battle.totalDmgToB,
            totalDmgTaken: battle.totalDmgToA,
            battleStats,
            missionName: mission.mission_name,
            npcLevel: missionEffectiveLevel,
        };
    } catch (e) {
        console.error('Mission collect error:', e);
        throw e;
    }
}

// ── Missions Collect (thin HTTP wrapper) ───────────────────────────────────
router.post('/missions/collect', auth, async (req, res) => {
    try {
        const db = await getDb();
        const character = await getCurrentCharacter(db, req.user.userId);
        if (!character) return res.status(404).json({ error: 'Character not found' });
        const result = await collectMissionForCharacter(db, character.id);
        if (result && result.__error) return res.status(result.__status || 400).json({ error: result.__error });
        res.json(result);
    } catch (e) {
        console.error('Mission collect error:', e);
        res.status(500).json({ error: e.message });
    }
});

// ── Auto-Complete missions (Premium: Arcane Reservoir) ─────────────────────
// Runs server-side so it keeps farming even while the account is logged off.
// A private MP pool is funded by converting up to 10 MP potions from
// inventory. Each started mission pays from global MP first, then the pool,
// and the cycle ends once the pool can't fund the next mission or the
// character turns it off. All activity uses dedicated /missions/auto-* markers
// so the anti-cheat recognizes it as intended behavior (never /missions/start
// or /missions/collect HTTP calls).

async function ensureAutoMissionTable(db) {
    await dbRun(db, `CREATE TABLE IF NOT EXISTS auto_mission_state (
        char_id INTEGER PRIMARY KEY,
        enabled INTEGER NOT NULL DEFAULT 0,
        current_map TEXT NOT NULL DEFAULT 'overworld',
        zone TEXT NOT NULL DEFAULT 'forest',
        spot TEXT NOT NULL DEFAULT '',
        mission_idx INTEGER NOT NULL DEFAULT 0,
        size TEXT NOT NULL DEFAULT 'small',
        auto_mp INTEGER NOT NULL DEFAULT 0,
        potions_loaded INTEGER NOT NULL DEFAULT 0,
        runs_completed INTEGER NOT NULL DEFAULT 0,
        last_result TEXT,
        updated_at INTEGER NOT NULL DEFAULT 0
    )`);
    try { await dbRun(db, "ALTER TABLE auto_mission_state ADD COLUMN hp_stop_enabled INTEGER NOT NULL DEFAULT 0"); } catch {}
    try { await dbRun(db, "ALTER TABLE auto_mission_state ADD COLUMN hp_stop_threshold INTEGER NOT NULL DEFAULT 0"); } catch {}
    try { await dbRun(db, "ALTER TABLE auto_mission_state ADD COLUMN hp_potion_stack TEXT"); } catch {}
    try { await dbRun(db, "ALTER TABLE auto_mission_state ADD COLUMN hp_heal_enabled INTEGER NOT NULL DEFAULT 0"); } catch {}
    try { await dbRun(db, "ALTER TABLE auto_mission_state ADD COLUMN hp_heal_threshold INTEGER NOT NULL DEFAULT 0"); } catch {}
    try { await dbRun(db, "ALTER TABLE auto_mission_state ADD COLUMN paused INTEGER NOT NULL DEFAULT 0"); } catch {}
}

async function ensureAutoMissionState(db, charId) {
    await ensureAutoMissionTable(db);
    await dbRun(db, 'INSERT OR IGNORE INTO auto_mission_state (char_id) VALUES (?)', [charId]);
    return dbGet(db, 'SELECT * FROM auto_mission_state WHERE char_id=?', [charId]);
}

async function listAutoPotions(db, charId) {
    const rows = await dbAll(db, "SELECT * FROM inventory WHERE char_id=? AND item_type='consumable'", [charId]);
    const mp = [];
    const hp = [];
    for (const r of rows) {
        let d; try { d = JSON.parse(r.item_data); } catch { continue; }
        const qty = Number(d.qty ?? 1);
        if (qty <= 0) continue;
        if (d.effect?.type === 'mp' && Number(d.effect?.value || 0) > 0) {
            const perMp = Number(d.effect.value);
            mp.push({
                inventoryId: r.id,
                id: d.id || 'mana_potion',
                name: d.name || 'Mana Potion',
                emoji: d.emoji || '💧',
                mp: perMp,
                qty,
                totalMp: perMp * qty,
            });
        } else if ((d.effect?.type === 'heal' || d.effect?.type === 'heal_full') && Number(d.effect?.value || 0) > 0) {
            const perHp = Number(d.effect.value);
            hp.push({
                inventoryId: r.id,
                id: d.id || 'health_potion',
                name: d.name || 'Health Potion',
                emoji: d.emoji || '🧪',
                heal: perHp,
                healFull: d.effect.type === 'heal_full',
                qty,
                totalHeal: perHp * qty,
            });
        }
    }
    return { mp, hp, maxHp: AUTO_MISSION_MAX_HP_POTIONS };
}

// Records a generic "intended behavior" marker in api_log under a dedicated
// auto path (never /missions/start or /missions/collect) for the anti-cheat.
async function markAutoIntended(db, charId, action) {
    try {
        // start/collect markers are written once per auto mission run and clutter
        // the admin action log (and churn the per-char 500-entry buffer); skip them.
        if (action === 'start' || action === 'collect') return;
        const char = await dbGet(db, 'SELECT name FROM characters WHERE id=?', [charId]);
        if (!char || !char.name) return;
        const now = Math.floor(Date.now() / 1000);
        const path = `/missions/auto-${action}`;
        await dbRun(db, `INSERT INTO api_log (user_id, username, char_name, method, path, status, req_body, tab_viewed, created_at)
            VALUES (0, ?, ?, 'POST', ?, 200, NULL, 0, ?)`,
            ['system', char.name, path, now]);
    } catch (e) { console.error('[AutoMission] marker error:', e.message); }
}

function autoRewardGold(zoneDef, difficulty, size) {
    const payout = (zoneDef && zoneDef.payoutBase && zoneDef.payoutBase[difficulty]) || [5, 10];
    const [minGold, maxGold] = payout;
    const baseGoldRoll = Math.floor(Math.random() * (maxGold - minGold + 1)) + minGold;
    const sizeConf = MISSION_SIZES[size] || MISSION_SIZES.small;
    return Math.floor(baseGoldRoll * MISSION_BASE_GOLD_MULT * sizeConf.rewardMult);
}

function autoRewardXp(size) {
    const map = { small: 6, medium: 9, large: 12 };
    const maxXp = map[size] || 6;
    return Math.max(0, Math.floor(Math.random() * (maxXp + 1)));
}

router.get('/missions/auto-status', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId);
        if (!char) return res.status(404).json({ error: 'Character not found' });
        const state = await ensureAutoMissionState(db, char.id);
        const activePrem = getActivePremium(char);
        const hasReservoir = hasPremium(activePrem, 'arcane_reservoir');
        let potionList;
        try { potionList = await listAutoPotions(db, char.id); } catch { potionList = { mp: [], hp: [] }; }
        let hpStack = [];
        try { hpStack = JSON.parse(state.hp_potion_stack || '[]'); } catch {}
        res.json({
            enabled: state.enabled === 1,
            paused: state.paused === 1,
            premium: hasReservoir,
            battleCooldownEndsAt: (() => {
                const lastBattle = char.last_battle_at || 0;
                const pvpCd = hasPremium(activePrem, 'fortune_hunter') ? Math.floor(600 * 0.50) : 600;
                return lastBattle > 0 ? lastBattle + pvpCd : 0;
            })(),
            zone: state.zone,
            spot: state.spot,
            missionIdx: state.mission_idx,
            size: state.size,
            currentMap: state.current_map,
            autoMp: state.auto_mp || 0,
            potionsLoaded: state.potions_loaded || 0,
            runs: state.runs_completed || 0,
            lastResult: state.last_result || '',
            hpStopEnabled: state.hp_stop_enabled === 1,
            hpStopThreshold: Number(state.hp_stop_threshold || 0),
            hpHealEnabled: Number(state.hp_heal_enabled || 0) === 1,
            hpHealThreshold: Number(state.hp_heal_threshold || 0),
            hpCurrent: Number(char.hp_current ?? char.hp_max ?? 0),
            hpMax: Number(char.hp_max ?? 0),
            mp: char.mission_points || 0,
            mpMax: hasReservoir ? MP_MAX * 2 : MP_MAX,
            maxPotions: AUTO_MISSION_MAX_POTIONS,
            maxHpPotions: AUTO_MISSION_MAX_HP_POTIONS,
            mpPotions: potionList.mp || [],
            hpPotions: potionList.hp || [],
            hpStack,
            potions: potionList.mp || [],
        });
    } catch (e) { console.error('[AutoMission] status error:', e); res.status(500).json({ error: e.message }); }
});

router.post('/missions/auto-enable', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId);
        if (!char) return res.status(404).json({ error: 'Character not found' });
        const activePrem = getActivePremium(char);
        if (!hasPremium(activePrem, 'arcane_reservoir')) {
            return res.status(403).json({ error: 'Auto-complete requires the Arcane Reservoir premium. Activate it to access auto-complete.' });
        }
        const { zone, spot, missionIdx, size, potionIds, potions, hpPotions, hpStopEnabled, hpStopThreshold, hpHealEnabled, hpHealThreshold } = req.body || {};
        const now = Math.floor(Date.now() / 1000);
        const currentMap = char.current_map || 'overworld';
        const zoneDef = currentMap === 'abyss' ? (ABYSS_ZONES[zone] || ZONES[zone]) : ZONES[zone];
        if (!zoneDef) return res.status(400).json({ error: 'Zone not found' });
        const spotDef = zoneDef.spots.find(s => String(s.id) === String(spot));
        if (!spotDef) return res.status(400).json({ error: 'Spot not found' });
        if (!['small', 'medium', 'large'].includes(size)) return res.status(400).json({ error: 'Invalid mission size' });
        if (String(char.location) !== String(zone)) {
            return res.status(400).json({ error: 'You must be located in this zone to auto-complete missions there.' });
        }
        const existing = await dbGet(db, 'SELECT id FROM active_missions WHERE character_id=?', [char.id]);
        if (existing) return res.status(400).json({ error: 'Finish your active mission before enabling auto-complete.' });

        // Convert selected MP-restoring potions into the private pool (max 10,
        // honoring stacked item quantities and explicit per-stack quantities).
        let loadedMp = 0, loadedCount = 0;
        let picks;
        if (Array.isArray(potions) && potions.length) {
            picks = potions.map(p => ({ invId: String(p?.inventoryId ?? p?.id ?? ''), qty: Math.max(0, Math.floor(Number(p?.qty) || 0)) }));
        } else {
            picks = (Array.isArray(potionIds) ? potionIds : []).map(invId => ({ invId: String(invId), qty: 0 }));
        }
        for (const pick of picks) {
            if (!pick.invId || loadedCount >= AUTO_MISSION_MAX_POTIONS) break;
            const item = await dbGet(db, 'SELECT * FROM inventory WHERE id=? AND char_id=?', [pick.invId, char.id]);
            if (!item) continue;
            let d; try { d = JSON.parse(item.item_data); } catch { continue; }
            const perMp = Number(d.effect?.value || 0);
            if (d.effect?.type !== 'mp' || perMp <= 0) continue;
            const qty = Number(d.qty ?? 1);
            // Legacy potionIds list consumes the whole stack; explicit picks use the requested count.
            const wanted = pick.qty > 0 ? Math.min(pick.qty, qty) : qty;
            const take = Math.min(wanted, AUTO_MISSION_MAX_POTIONS - loadedCount);
            if (take <= 0) break;
            loadedMp += take * perMp;
            loadedCount += take;
            if (take >= qty) {
                await dbRun(db, 'DELETE FROM inventory WHERE id=?', [pick.invId]);
            } else {
                d.qty = qty - take;
                await dbRun(db, 'UPDATE inventory SET item_data=? WHERE id=?', [JSON.stringify(d), pick.invId]);
            }
        }

        const hpEnabled = !!hpStopEnabled;
        const hpThreshold = hpEnabled ? Math.max(1, Math.floor(Number(hpStopThreshold || 10))) : 0;

        // Load selected HP-restoring potions into a stack (max 3). Each entry is
        // one potion use worth of healing; consumed one at a time during low-HP.
        const hpStack = [];
        const hpPicks = (Array.isArray(hpPotions) ? hpPotions : [])
            .map(p => ({ invId: String(p?.inventoryId ?? p?.id ?? ''), qty: Math.max(0, Math.floor(Number(p?.qty) || 0)) }))
            .filter(p => p.invId);
        for (const pick of hpPicks) {
            if (hpStack.length >= AUTO_MISSION_MAX_HP_POTIONS) break;
            const item = await dbGet(db, 'SELECT * FROM inventory WHERE id=? AND char_id=?', [pick.invId, char.id]);
            if (!item) continue;
            let d; try { d = JSON.parse(item.item_data); } catch { continue; }
            const isHealFull = d.effect?.type === 'heal_full';
            const perHp = Number(d.effect?.value || 0);
            if (!('heal' === d.effect?.type || isHealFull) || perHp <= 0) continue;
            const qty = Number(d.qty ?? 1);
            const wanted = pick.qty > 0 ? Math.min(pick.qty, qty) : qty;
            const take = Math.min(wanted, AUTO_MISSION_MAX_HP_POTIONS - hpStack.length);
            for (let i = 0; i < take; i++) hpStack.push({ invId: pick.invId, heal: perHp, healFull: isHealFull ? 1 : 0 });
            if (take >= qty) {
                await dbRun(db, 'DELETE FROM inventory WHERE id=?', [pick.invId]);
            } else {
                d.qty = qty - take;
                await dbRun(db, 'UPDATE inventory SET item_data=? WHERE id=?', [JSON.stringify(d), pick.invId]);
            }
        }
        const hpHealOn = !!hpHealEnabled && hpStack.length > 0;
        const hpHealThr = hpHealOn ? Math.max(1, Math.floor(Number(hpHealThreshold || 50))) : 0;

        await dbRun(db, `INSERT INTO auto_mission_state (char_id, enabled, current_map, zone, spot, mission_idx, size, auto_mp, potions_loaded, hp_stop_enabled, hp_stop_threshold, hp_potion_stack, hp_heal_enabled, hp_heal_threshold, updated_at)
            VALUES (?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(char_id) DO UPDATE SET
                enabled=1, current_map=excluded.current_map, zone=excluded.zone, spot=excluded.spot,
                mission_idx=excluded.mission_idx, size=excluded.size,
                auto_mp=excluded.auto_mp, potions_loaded=excluded.potions_loaded,
                hp_stop_enabled=excluded.hp_stop_enabled, hp_stop_threshold=excluded.hp_stop_threshold,
                hp_potion_stack=excluded.hp_potion_stack,
                hp_heal_enabled=excluded.hp_heal_enabled, hp_heal_threshold=excluded.hp_heal_threshold,
                paused=0, last_result=NULL, updated_at=excluded.updated_at`,
            [char.id, currentMap, zone, spot, missionIdx, size, loadedMp, loadedCount, hpEnabled ? 1 : 0, hpThreshold, JSON.stringify(hpStack), hpHealOn ? 1 : 0, hpHealThr, now]);

        await markAutoIntended(db, char.id, 'enable');
        const state = await ensureAutoMissionState(db, char.id);
        res.json({
            success: true,
            autoMp: state.auto_mp || 0,
            hpStack: JSON.parse(state.hp_potion_stack || '[]'),
            message: `Auto-complete enabled for ${spotDef.name}. ${loadedCount} potion(s) loaded (+${loadedMp} MP)${hpStack.length ? `, ${hpStack.length} HP potion(s) loaded.` : '.'}`,
        });
    } catch (e) { console.error('[AutoMission] enable error:', e); res.status(500).json({ error: e.message }); }
});

router.post('/missions/auto-disable', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId);
        if (!char) return res.status(404).json({ error: 'Character not found' });
await dbRun(db, 'UPDATE auto_mission_state SET enabled=0, last_result=? WHERE char_id=?', ['Stopped by player', char.id]);
        await markAutoIntended(db, char.id, 'disable');
        res.json({ success: true, message: 'Auto-complete disabled.' });
    } catch (e) { console.error('[AutoMission] disable error:', e.message); res.status(500).json({ error: e.message }); }
});

router.post('/missions/auto-pause', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId);
        if (!char) return res.status(404).json({ error: 'Character not found' });
        const state = await ensureAutoMissionState(db, char.id);
        if (state.enabled !== 1) return res.status(400).json({ error: 'Auto-complete is not running.' });
        await dbRun(db, 'UPDATE auto_mission_state SET paused=1, last_result=?, updated_at=? WHERE char_id=?', ['Paused by player', Math.floor(Date.now()/1000), char.id]);
        await markAutoIntended(db, char.id, 'pause');
        const updated = await ensureAutoMissionState(db, char.id);
        res.json({ success: true, message: 'Auto-complete paused.', paused: updated.paused === 1 });
    } catch (e) { console.error('[AutoMission] pause error:', e.message); res.status(500).json({ error: e.message }); }
});

