router.get('/chat/history', auth, async (req, res) => {
    try {
        const db = await getDb();
        await purgeExpiredChatMessages(db);
        const char = await getCurrentCharacter(db, req.user.userId, 'id,name');
        if (!char) return res.status(404).json({ error: 'No character' });
        const sinceId = Math.max(0, Number(req.query?.since || 0));
        const squadRow = await dbGet(db, 'SELECT squad_id FROM squad_members WHERE char_id=? LIMIT 1', [char.id]);
        const squadId = squadRow?.squad_id ? Number(squadRow.squad_id) : null;
        let rows = [];
        if (sinceId > 0) {
            rows = await dbAll(
                db,
                `SELECT *
                 FROM chat_messages
                 WHERE (
                        (recipient_char_id IS NULL AND squad_id IS NULL)
                        OR (recipient_char_id IS NOT NULL AND (sender_char_id = ? OR recipient_char_id = ?))
                        ${squadId ? `OR (squad_id = ${squadId} AND recipient_char_id IS NULL)` : ''}
                    )
                   AND id > ?
                 ORDER BY id ASC
                 LIMIT 80`,
                [char.id, char.id, sinceId]
            );
        } else {
            rows = await dbAll(
                db,
                `SELECT *
                 FROM chat_messages
                 WHERE
                    (recipient_char_id IS NULL AND squad_id IS NULL)
                    OR (recipient_char_id IS NOT NULL AND (sender_char_id = ? OR recipient_char_id = ?))
                    ${squadId ? `OR (squad_id = ${squadId} AND recipient_char_id IS NULL)` : ''}
                 ORDER BY id DESC
                 LIMIT 60`,
                [char.id, char.id]
            );
            rows.reverse();
        }
        res.json({ messages: rows.map(row => serializeChatMessage(row, char.id)), squadId });
    } catch (e) {
        console.error('Chat history failed:', e);
        res.status(500).json({ error: e.message });
    }
});
router.get('/chat/characters', auth, async (req, res) => {
    try {
        const db = await getDb();
        const char = await getCurrentCharacter(db, req.user.userId, 'id');
        if (!char) return res.status(404).json({ error: 'No character' });

        const rawQuery = String(req.query?.q || '').trim().toLowerCase();
        const prefixQuery = rawQuery ? `${rawQuery}%` : '';
        const containsQuery = rawQuery ? `%${rawQuery}%` : '';

        const rows = await dbAll(
            db,
            `SELECT id, name
             FROM characters
             WHERE id != ?
               AND (
                    ? = ''
                    OR lower(name) LIKE ?
                    OR lower(name) LIKE ?
               )
             ORDER BY
                CASE
                    WHEN ? != '' AND lower(name) = ? THEN 0
                    WHEN ? != '' AND lower(name) LIKE ? THEN 1
                    ELSE 2
                END,
                name COLLATE NOCASE ASC
             LIMIT 8`,
            [
                char.id,
                rawQuery,
                prefixQuery,
                containsQuery,
                rawQuery,
                rawQuery,
                rawQuery,
                prefixQuery
            ]
        );

        res.json({
            characters: rows.map(row => ({
                id: Number(row.id),
                name: row.name
            }))
        });
    } catch (e) {
        console.error('Chat character lookup failed:', e);
        res.status(500).json({ error: e.message });
    }
});
router.post('/chat/send', auth, async (req, res) => {
    try {
        const db = await getDb();
        await purgeExpiredChatMessages(db);
        const sender = await getCurrentCharacter(db, req.user.userId, 'id,name');
        if (!sender) return res.status(404).json({ error: 'No character' });

        const rawMessage = String(req.body?.message || '');
        const messageText = sanitizeChatMessage(rawMessage);
        if (!messageText) return res.status(400).json({ error: 'Message required.' });

        const recipientInput = String(req.body?.recipientName || '').trim();
        const channel = String(req.body?.channel || 'global').trim();

        let recipient = null;
        let squadId = null;

        if (channel === 'squad') {
            const membership = await dbGet(db, 'SELECT squad_id FROM squad_members WHERE char_id=? LIMIT 1', [sender.id]);
            if (!membership?.squad_id) return res.status(403).json({ error: 'You are not in a squad.' });
            squadId = Number(membership.squad_id);
        } else if (recipientInput) {
            recipient = await dbGet(
                db,
                'SELECT id, name FROM characters WHERE lower(name) = lower(?) LIMIT 1',
                [recipientInput]
            );
            if (!recipient) return res.status(404).json({ error: 'Character not found.' });
            if (Number(recipient.id) === Number(sender.id)) {
                return res.status(400).json({ error: 'Cannot message yourself.' });
            }
        }

        const createdAt = Math.floor(Date.now() / 1000);
        await dbRun(
            db,
            `INSERT INTO chat_messages
                (sender_user_id, sender_char_id, sender_name, recipient_char_id, recipient_name, message_text, created_at, squad_id)
             VALUES (?,?,?,?,?,?,?,?)`,
            [
                req.user.userId,
                sender.id,
                sender.name,
                recipient?.id || null,
                recipient?.name || null,
                messageText,
                createdAt,
                squadId
            ]
        );

        const inserted = await dbGet(db, 'SELECT * FROM chat_messages WHERE id = last_insert_rowid()');
        res.json({
            success: true,
            message: serializeChatMessage(inserted, sender.id)
        });
    } catch (e) {
        console.error('Chat send failed:', e);
        res.status(500).json({ error: e.message });
    }
});

