function appendFlag(map, key, val) {
    const prev = map.get(key);
    map.set(key, prev ? prev + ' ||| ' + val : val);
}

// Longest wall-clock window (ms) during which log entries arrived continuously
// (consecutive gaps <= gapMaxMs). A bot is active for hours on end; a human
// logs in short bursts (minutes) separated by long idle gaps. This separates
// the two even when a human's total call count / span / rate look bot-like.
function longestActiveSpanMs(sortedTs, gapMaxMs) {
    if (!sortedTs.length) return 0;
    let best = 0;
    let runStart = sortedTs[0];
    let prev = sortedTs[0];
    for (let i = 1; i < sortedTs.length; i++) {
        const ts = sortedTs[i];
        if (ts - prev > gapMaxMs) {
            best = Math.max(best, prev - runStart);
            runStart = ts;
        }
        prev = ts;
    }
    best = Math.max(best, prev - runStart);
    return best;
}

// ── Bot Detection Engine ────────────────────────────────────────────
async function runBotDetection(db) {
    const setting = await dbGet(db, 'SELECT value FROM server_settings WHERE key=?', ['bot_detection_enabled']);
    const globalOn = !(setting && setting.value === 'false');

    // When global is OFF, only scan individually marked (🟢) characters
    let scanEnabledSet = null;
    if (!globalOn) {
        try {
            const rows = await db.execute('SELECT char_name FROM flagged_characters WHERE scan_enabled = 1');
            scanEnabledSet = new Set(rows.rows.map(r => r.char_name));
            if (scanEnabledSet.size === 0) return new Map();
        } catch { return new Map(); }
    }

    const botPlayers = new Map();
    const now = Math.floor(Date.now() / 1000);
    try {
        const bots = await db.execute('SELECT DISTINCT c.name FROM bot_configs bc JOIN characters c ON bc.char_id = c.id WHERE bc.enabled = 1');
        for (const row of bots.rows) {
            if (row.name && (!scanEnabledSet || scanEnabledSet.has(row.name))) appendFlag(botPlayers, row.name, 'Managed test bot');
        }
    } catch (e) { console.error('[bot-detect] bot_configs error:', e.message); }
    try {
        const fpCutoff = now - 86400;
        const fpRows = await db.execute({ sql: `SELECT char_name, created_at, path FROM api_log WHERE created_at > ? AND method = 'POST' ORDER BY char_name, created_at LIMIT 20000`, args: [fpCutoff] });
        const fpGroups = {};
        for (const r of fpRows.rows) {
            const name = r.char_name;
            if (!name || name === '?' || !r.created_at) continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            const p = (r.path || '').toLowerCase();
            if (!p.includes('/missions/')) continue;
            if (!fpGroups[name]) fpGroups[name] = [];
            fpGroups[name].push({ ts: r.created_at, path: p });
        }
        for (const [name, entries] of Object.entries(fpGroups)) {
            entries.sort((a, b) => a.ts - b.ts);
            let instantStarts = 0;
            for (let i = 1; i < entries.length; i++) {
                const prev = entries[i - 1].path;
                const cur = entries[i].path;
                const gap = entries[i].ts - entries[i - 1].ts;
                if (gap < 2 && cur.includes('/missions/start') && (prev.includes('/missions/collect') || prev.includes('/dungeon/mp-spent'))) instantStarts++;
            }
            if (instantStarts >= 5) appendFlag(botPlayers, name, `Instant collect\u2192start: ${instantStarts} times in 24h`);
            const noTick = _missionNoTickStarts.get(name) || 0;
            if (noTick >= 5) appendFlag(botPlayers, name, `No UI tick: ${noTick} direct starts`);
        }
    } catch (e) { console.error('[bot-detect] mission instant starts error:', e.message); }
    try {
        const cutoff = now - 86400;
        const rows = await db.execute({ sql: `SELECT char_name, created_at, path FROM api_log WHERE created_at > ? AND method = 'POST' ORDER BY char_name, created_at LIMIT 20000`, args: [cutoff] });
        const groups = {};
        for (const r of rows.rows) {
            const name = r.char_name;
            if (!name || name === '?' || !r.created_at) continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            const p = (r.path || '').toLowerCase();
            if (!p.includes('/missions/') && !p.includes('/dungeon/mp-spent')) continue;
            if (!groups[name]) groups[name] = [];
            groups[name].push(r.created_at);
        }
        for (const [name, timestamps] of Object.entries(groups)) {
            timestamps.sort((a, b) => a - b);
            const unique = timestamps.filter((t, i) => i === 0 || t !== timestamps[i - 1]);
            if (unique.length < 20) continue;
            const gaps = [];
            for (let i = 1; i < unique.length; i++) { const g = unique[i] - unique[i - 1]; if (g >= 3) gaps.push(g); }
            if (gaps.length < 15) continue;
            const sum = gaps.reduce((s, v) => s + v, 0);
            const mean = sum / gaps.length;
            const variance = gaps.reduce((s, v) => s + (v - mean) ** 2, 0) / gaps.length;
            const stddev = Math.sqrt(variance);
            const cv = stddev / mean;
            const maxGap = Math.max(...gaps);
            if (cv < 0.5 && mean >= 60 && mean <= 900 && maxGap < 1800) appendFlag(botPlayers, name, `Mission timing CV=${cv.toFixed(2)}, mean=${Math.round(mean)}s`);
        }
    } catch (e) { console.error('[bot-detect] mission timing error:', e.message); }
    try {
        const mcCutoff = now - 86400;
        const mcRows = await db.execute({ sql: `SELECT char_name, created_at FROM api_log WHERE created_at > ? AND method = 'POST' AND path LIKE '%/missions/collect%' ORDER BY char_name, created_at`, args: [mcCutoff] });
        if (mcRows.rows.length > 0) console.log('[bot-detect] Mission collect rows:', mcRows.rows.length, 'first:', mcRows.rows[0]?.char_name);
        const mcGroups = {};
        for (const r of mcRows.rows) {
            const name = r.char_name;
            if (!name || name === '?' || !r.created_at) continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            if (!mcGroups[name]) mcGroups[name] = [];
            mcGroups[name].push(r.created_at);
        }
        for (const [name, timestamps] of Object.entries(mcGroups)) {
            timestamps.sort((a, b) => a - b);
            if (timestamps.length < 6) continue;
            const gaps = [];
            for (let i = 1; i < timestamps.length; i++) { const g = timestamps[i] - timestamps[i - 1]; if (g >= 60 && g <= 3600) gaps.push(g); }
            if (gaps.length < 5) continue;
            const mean = gaps.reduce((s, v) => s + v, 0) / gaps.length;
            const variance = gaps.reduce((s, v) => s + (v - mean) ** 2, 0) / gaps.length;
            const cv = Math.sqrt(variance) / mean;
            if (cv < 0.2) appendFlag(botPlayers, name, `Mission cycle: ${timestamps.length} collects in 24h, mean=${Math.round(mean)}s, CV=${cv.toFixed(3)}`);
        }
    } catch (e) { console.error('[bot-detect] mission cycle error:', e.message); }
    try {
        const bCutoff = now - 21600;
        const bRows = await db.execute({ sql: `SELECT ca.name AS char_name, b.fought_at FROM battles b JOIN characters ca ON b.attacker_id = ca.id WHERE b.fought_at > ? ORDER BY ca.name, b.fought_at`, args: [bCutoff] });
        const bGroups = {};
        for (const r of bRows.rows) {
            const name = r.char_name;
            if (!name || name === '?' || !r.fought_at) continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            if (!bGroups[name]) bGroups[name] = [];
            bGroups[name].push(r.fought_at);
        }
        for (const [name, timestamps] of Object.entries(bGroups)) {
            timestamps.sort((a, b) => a - b);
            const unique = timestamps.filter((t, i) => i === 0 || t !== timestamps[i - 1]);
            if (unique.length < 50) continue;
            const gaps = [];
            for (let i = 1; i < unique.length; i++) gaps.push(unique[i] - unique[i - 1]);
            const sum = gaps.reduce((s, v) => s + v, 0);
            const mean = sum / gaps.length;
            const variance = gaps.reduce((s, v) => s + (v - mean) ** 2, 0) / gaps.length;
            const stddev = Math.sqrt(variance);
            const cv = stddev / mean;
            const maxGap = Math.max(...gaps);
            if (cv < 0.5 && mean < 60 && maxGap < 300) appendFlag(botPlayers, name, `Battle timing CV=${cv.toFixed(2)}, mean=${Math.round(mean)}s`);
        }
    } catch (e) { console.error('[bot-detect] battle timing error:', e.message); }
    try {
        const cPcutoff = now - 86400;
        const cRows = await db.execute({ sql: `SELECT char_name, created_at FROM api_log WHERE created_at > ? AND method = 'GET' AND (path LIKE '%/character%' OR path LIKE '%/inventory%' OR path LIKE '%/missions%' OR path LIKE '%/status%') ORDER BY char_name, created_at`, args: [cPcutoff] });
        if (cRows.rows.length > 0) console.log('[bot-detect] ConstPoll total rows:', cRows.rows.length, 'distinct chars:', [...new Set(cRows.rows.map(r=>r.char_name))].slice(0,10));
        const cGroups = {};
        for (const r of cRows.rows) {
            const name = r.char_name;
            if (!name || name === '?' || !r.created_at) continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            if (!cGroups[name]) cGroups[name] = [];
            cGroups[name].push(r.created_at);
        }
        for (const [name, timestamps] of Object.entries(cGroups)) {
            timestamps.sort((a, b) => a - b);
            if (timestamps.length < 50) continue;
            const span = timestamps[timestamps.length - 1] - timestamps[0];
            if (span < 7200) continue;
            const reqPerMin = timestamps.length / (span / 60);
            if (reqPerMin < 1.0) continue;
            const gaps = [];
            for (let i = 1; i < timestamps.length; i++) { const g = timestamps[i] - timestamps[i - 1]; if (g > 0 && g < 300) gaps.push(g); }
            if (gaps.length < 30) continue;
            const mean = gaps.reduce((s, v) => s + v, 0) / gaps.length;
            if (mean >= 120) continue;
            const variance = gaps.reduce((s, v) => s + (v - mean) ** 2, 0) / gaps.length;
            const cv = Math.sqrt(variance) / mean;
            if (['Vader','vader','Sanctus','En Peasant','en peasant','Forsaken','forsaken'].includes(name)) console.log('[bot-detect] cp debug:', name, 'entries:', timestamps.length, 'span:', Math.round(span/60)+'min', 'rate:', reqPerMin.toFixed(1)+'/min', 'mean:', Math.round(mean)+'s', 'cv:', cv.toFixed(2), 'gaps:', gaps.length);
            if (cv < 1.5) {
                const prev = await dbGet(db, 'SELECT signal_count FROM flagged_characters WHERE char_name=?', [name]);
                const countNote = (prev && prev.signal_count > 1) ? ` (${prev.signal_count}x flagged)` : '';
                appendFlag(botPlayers, name, `Frequent polling: ${timestamps.length} hits in ${Math.round(span/60)}min, ${reqPerMin.toFixed(1)}/min, mean=${Math.round(mean)}s${countNote}`);
            }
        }
    } catch (e) { console.error('[bot-detect] constant polling error:', e.message); }
    try {
        const bpCutoff = now - 86400;
        const bpRows = await db.execute({ sql: `SELECT char_name, path, created_at FROM api_log WHERE created_at > ? ORDER BY created_at DESC LIMIT 50000`, args: [bpCutoff] });
        const bpGroups = {};
        for (const r of bpRows.rows) {
            const name = r.char_name;
            if (!name || name === '?' || !r.created_at) continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            const p = (r.path || '').toLowerCase();
            if (p.includes('/chat/') || p.includes('/admin/')) continue;
            if (!bpGroups[name]) bpGroups[name] = [];
            bpGroups[name].push({ path: r.path, ts: r.created_at });
        }
        for (const [name, entries] of Object.entries(bpGroups)) {
            const recent = entries.slice(0, 500);
            if (recent.length < 120) continue;
            recent.sort((a, b) => a.ts - b.ts);
            const span = recent[recent.length - 1].ts - recent[0].ts;
            if (span < 600) continue;
            const reqPerMin = recent.length / (span / 60);
            if (reqPerMin < 1.0) continue;
            const paths = new Set();
            for (const e of recent) {
                let p = (e.path || '').toLowerCase();
                p = p.split('?')[0];
                p = p.replace(/\/\d+$/, '');
                paths.add(p);
            }
            const hasAchievements = [...paths].some(p => p.includes('/achievements'));
            const pathCounts = {};
            for (const e of recent) {
                let p = (e.path || '').toLowerCase();
                p = p.split('?')[0];
                p = p.replace(/\/\d+$/, '');
                pathCounts[p] = (pathCounts[p] || 0) + 1;
            }
            const maxPathRatio = Math.max(...Object.values(pathCounts)) / recent.length;
            const topPath = Object.entries(pathCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || '';
            const botPollEndpoints = ['/character', '/missions/active', '/missions/ui-tick', '/inventory'];
            const isBotPoll = botPollEndpoints.some(e => topPath.includes(e));
            const activeSpan = longestActiveSpanMs(recent.map(e => e.ts), 150000);
            if (['Vader','vader','Sanctus','En Peasant','en peasant','Forsaken','forsaken'].includes(name)) console.log('[bot-detect] bp debug:', name, 'entries:', recent.length, 'span:', Math.round(span/60)+'min', 'active:', Math.round(activeSpan/60000)+'min', 'rate:', reqPerMin.toFixed(1)+'/min', 'paths:', paths.size, 'maxPathRatio:', (maxPathRatio*100).toFixed(0)+'%', 'topPath:', topPath, 'isBotPoll:', isBotPoll);
            if (isBotPoll && maxPathRatio > 0.2 && activeSpan >= 3600000) {
                const prev = await dbGet(db, 'SELECT signal_count FROM flagged_characters WHERE char_name=?', [name]);
                const countNote = (prev && prev.signal_count > 1) ? ` (${prev.signal_count}x flagged)` : '';
                appendFlag(botPlayers, name, `Bot pattern: ${recent.length} calls, ${Math.round(span/60)}min, ${reqPerMin.toFixed(1)}/min, top endpoint ${Math.round(maxPathRatio*100)}% of calls, active ${Math.round(activeSpan/60000)}min continuous${countNote}`);
            }
        }
    } catch (e) { console.error('[bot-detect] bot pattern error:', e.message); }
    try {
        const pCutoff = now - 86400;
        const pRows = await db.execute({ sql: `SELECT char_name, created_at, path FROM api_log WHERE created_at > ? AND method = 'GET' AND path NOT LIKE '%/chat/%' AND (path LIKE '%/character%' OR path LIKE '%/inventory%' OR path LIKE '%/missions/active%' OR path LIKE '%/travel/status%' OR path LIKE '%/achievements%' OR path LIKE '%/setups%' OR path LIKE '%/messages/%') ORDER BY char_name, created_at LIMIT 10000`, args: [pCutoff] });
        const pGroups = {};
        for (const r of pRows.rows) {
            const name = r.char_name;
            if (!name || name === '?' || !r.created_at) continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            if (!pGroups[name]) pGroups[name] = [];
            pGroups[name].push(r.created_at);
        }
        for (const [name, timestamps] of Object.entries(pGroups)) {
            timestamps.sort((a, b) => a - b);
            const unique = timestamps.filter((t, i) => i === 0 || t !== timestamps[i - 1]);
            if (unique.length < 15) continue;
            const span = unique[unique.length - 1] - unique[0];
            if (span < 3600) continue;
            const allGaps = [];
            for (let i = 1; i < unique.length; i++) allGaps.push(unique[i] - unique[i - 1]);
            const shortGaps = allGaps.filter(g => g < 120);
            const activeTime = shortGaps.reduce((s, v) => s + v, 0);
            const ratio = shortGaps.length / allGaps.length;
            const isSustained = span > 7200; // > 2h coverage
            const isRelentless = ratio > 0.9; // almost no breaks at all
            if (shortGaps.length >= 10 && activeTime >= 1800) {
                if (ratio > 0.6) {
                    const mean = shortGaps.reduce((s, v) => s + v, 0) / shortGaps.length;
                    const variance = shortGaps.reduce((s, v) => s + (v - mean) ** 2, 0) / shortGaps.length;
                    const cv = Math.sqrt(variance) / mean;
                    if (['Vader','vader','Sanctus','En Peasant','en peasant','Forsaken','forsaken'].includes(name)) console.log('[bot-detect] sp debug:', name, 'unique:', unique.length, 'span:', Math.round(span/60)+'min', 'shortGaps:', shortGaps.length+'/'+allGaps.length, 'active:', Math.round(activeTime/60)+'min', 'ratio:', ratio.toFixed(2), 'CV:', cv.toFixed(2), 'relentless:', isRelentless, 'sustained:', isSustained);
                    if (cv < 0.8 || (isRelentless && isSustained)) {
                        appendFlag(botPlayers, name, `State polling: ${shortGaps.length}/${allGaps.length} gaps < 120s, ${Math.round(activeTime/60)}min active, CV=${cv.toFixed(2)}`);
                    }
                }
            }
        }
    } catch (e) { console.error('[bot-detect] state polling error:', e.message); }
    try {
        const nhFlags = await collectNoHumanInputFlags(db, null, scanEnabledSet, now);
        for (const [name, reason] of nhFlags) appendFlag(botPlayers, name, reason);
    } catch (e) { console.error('[bot-detect] no human input error:', e.message); }
    if (botPlayers.size > 0) console.log('[bot-detect] Detected:', [...botPlayers.entries()].map(([k,v])=>k+': '+v).join(', '));
    return botPlayers;
}

async function runSelectiveBotDetection(db, charName) {
    // Check if scan is enabled for this character (skip if explicitly disabled)
    try {
        const flagRow = await dbGet(db, 'SELECT scan_enabled FROM flagged_characters WHERE char_name=?', [charName]);
        if (flagRow && flagRow.scan_enabled === 0) return new Map();
    } catch {}

    const botPlayers = new Map();
    const now = Math.floor(Date.now() / 1000);

    // 1. Managed test bots
    try {
        const bots = await db.execute({ sql: 'SELECT DISTINCT c.name FROM bot_configs bc JOIN characters c ON bc.char_id = c.id WHERE bc.enabled = 1 AND c.name = ?', args: [charName] });
        for (const row of bots.rows) {
            if (row.name) appendFlag(botPlayers, row.name, 'Managed test bot');
        }
    } catch (e) { console.error('[bot-detect] selective bot_configs error:', e.message); }
    
    // 2. Mission instant starts
    try {
        const fpCutoff = now - 86400;
        const fpRows = await db.execute({ sql: `SELECT char_name, created_at, path FROM api_log WHERE char_name = ? AND created_at > ? AND method = 'POST' ORDER BY char_name, created_at`, args: [charName, fpCutoff] });
        const entries = fpRows.rows.map(r => ({ ts: r.created_at, path: (r.path || '').toLowerCase() }))
            .filter(r => r.path.includes('/missions/'));
        
        entries.sort((a, b) => a.ts - b.ts);
        let instantStarts = 0;
        for (let i = 1; i < entries.length; i++) {
            const prev = entries[i - 1].path;
            const cur = entries[i].path;
            const gap = entries[i].ts - entries[i - 1].ts;
            if (gap < 2 && cur.includes('/missions/start') && (prev.includes('/missions/collect') || prev.includes('/dungeon/mp-spent'))) instantStarts++;
        }
        if (instantStarts >= 5) appendFlag(botPlayers, charName, `Instant collect\u2192start: ${instantStarts} times in 24h`);
        
        const noTick = _missionNoTickStarts.get(charName) || 0;
        if (noTick >= 5) appendFlag(botPlayers, charName, `No UI tick: ${noTick} direct starts`);
    } catch (e) { console.error('[bot-detect] selective mission error:', e.message); }

    // 3. Mission cycle timing (collect-to-collect gaps)
    try {
        const mcCutoff = now - 86400;
        const mcRows = await db.execute({ sql: `SELECT created_at FROM api_log WHERE char_name = ? AND created_at > ? AND method = 'POST' AND path LIKE '%/missions/collect%' ORDER BY created_at`, args: [charName, mcCutoff] });
        const mcTimestamps = mcRows.rows.map(r => r.created_at).filter(Boolean).sort((a, b) => a - b);
        if (mcTimestamps.length >= 6) {
            const gaps = [];
            for (let i = 1; i < mcTimestamps.length; i++) { const g = mcTimestamps[i] - mcTimestamps[i - 1]; if (g >= 60 && g <= 3600) gaps.push(g); }
            if (gaps.length >= 5) {
                const mean = gaps.reduce((s, v) => s + v, 0) / gaps.length;
                const variance = gaps.reduce((s, v) => s + (v - mean) ** 2, 0) / gaps.length;
                const cv = Math.sqrt(variance) / mean;
                if (cv < 0.2) appendFlag(botPlayers, charName, `Mission cycle: ${mcTimestamps.length} collects in 24h, mean=${Math.round(mean)}s, CV=${cv.toFixed(3)}`);
            }
        }
    } catch (e) { console.error('[bot-detect] selective mission cycle error:', e.message); }

    // 4. Constant polling
    try {
        const cpCutoff = now - 86400;
        const cpRows = await db.execute({ sql: `SELECT created_at FROM api_log WHERE char_name = ? AND created_at > ? AND method = 'GET' AND (path LIKE '%/character%' OR path LIKE '%/inventory%' OR path LIKE '%/missions%' OR path LIKE '%/status%') ORDER BY created_at`, args: [charName, cpCutoff] });
        const timestamps = cpRows.rows.map(r => r.created_at).filter(Boolean);
        timestamps.sort((a, b) => a - b);
        if (timestamps.length >= 50) {
            const span = timestamps[timestamps.length - 1] - timestamps[0];
            if (span >= 7200) {
                const reqPerMin = timestamps.length / (span / 60);
                if (reqPerMin >= 1.0) {
                const gaps = [];
                for (let i = 1; i < timestamps.length; i++) { const g = timestamps[i] - timestamps[i - 1]; if (g > 0 && g < 300) gaps.push(g); }
                if (gaps.length >= 30) {
                    const mean = gaps.reduce((s, v) => s + v, 0) / gaps.length;
                    if (mean < 120) {
                        const variance = gaps.reduce((s, v) => s + (v - mean) ** 2, 0) / gaps.length;
                        const cv = Math.sqrt(variance) / mean;
                        if (cv < 1.5) {
                            const prev = await dbGet(db, 'SELECT signal_count FROM flagged_characters WHERE char_name=?', [charName]);
                            const countNote = (prev && prev.signal_count > 1) ? ` (${prev.signal_count}x flagged)` : '';
                            appendFlag(botPlayers, charName, `Frequent polling: ${timestamps.length} hits in ${Math.round(span/60)}min, ${reqPerMin.toFixed(1)}/min, mean=${Math.round(mean)}s${countNote}`);
                        }
                    }
                }
                }
            }
        }
    } catch (e) { console.error('[bot-detect] selective constant polling error:', e.message); }
    try {
        const bpCutoff = now - 86400;
        const bpRows = await db.execute({ sql: `SELECT path, created_at FROM api_log WHERE char_name = ? AND created_at > ? ORDER BY created_at DESC LIMIT 500`, args: [charName, bpCutoff] });
        const filtered = bpRows.rows.filter(r => {
            const p = (r.path || '').toLowerCase();
            return !p.includes('/chat/') && !p.includes('/admin/');
        });
        if (filtered.length >= 120) {
            const entries = filtered;
            entries.sort((a, b) => a.created_at - b.created_at);
            const span = entries[entries.length - 1].created_at - entries[0].created_at;
            if (span >= 600) {
                const reqPerMin = entries.length / (span / 60);
                if (reqPerMin >= 1.0) {
                    const paths = new Set();
                    for (const r of entries) {
                        let p = (r.path || '').toLowerCase();
                        p = p.split('?')[0];
                        p = p.replace(/\/\d+$/, '');
                        paths.add(p);
                    }
                    const hasAchievements = [...paths].some(p => p.includes('/achievements'));
                    const pathCounts = {};
                    for (const e of entries) {
                        let p = (e.path || '').toLowerCase();
                        p = p.split('?')[0];
                        p = p.replace(/\/\d+$/, '');
                        pathCounts[p] = (pathCounts[p] || 0) + 1;
                    }
                    const maxPathRatio = Math.max(...Object.values(pathCounts)) / entries.length;
                    const topPath = Object.entries(pathCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || '';
                    const botPollEndpoints = ['/character', '/missions/active', '/missions/ui-tick', '/inventory'];
                    const isBotPoll = botPollEndpoints.some(e => topPath.includes(e));
                    const activeSpan = longestActiveSpanMs(entries.map(e => e.created_at), 150000);
                    if (isBotPoll && maxPathRatio > 0.2 && activeSpan >= 3600000) {
                        const prev = await dbGet(db, 'SELECT signal_count FROM flagged_characters WHERE char_name=?', [charName]);
                        const countNote = (prev && prev.signal_count > 1) ? ` (${prev.signal_count}x flagged)` : '';
                        appendFlag(botPlayers, charName, `Bot pattern: ${entries.length} calls, ${Math.round(span/60)}min, ${reqPerMin.toFixed(1)}/min, top endpoint ${Math.round(maxPathRatio*100)}% of calls, active ${Math.round(activeSpan/60000)}min continuous${countNote}`);
                    }
                }
            }
        }
    } catch (e) { console.error('[bot-detect] selective bot pattern error:', e.message); }

    // 6. No human input while the game keeps running
    try {
        const nhFlags = await collectNoHumanInputFlags(db, charName, null, now);
        for (const [name, reason] of nhFlags) appendFlag(botPlayers, name, reason);
    } catch (e) { console.error('[bot-detect] selective no human input error:', e.message); }

    return botPlayers;
}

// Detects characters whose game keeps running (missions/battles/polling) while
// the client reported zero human input (mouse/keyboard/touch) for a long window.
// Returns [[name, reason], ...]. Position data is never tracked or stored.
async function collectNoHumanInputFlags(db, charName, scanEnabledSet, now) {
    const flags = [];
    const cutoff = now - 6 * 3600; // 6h window
    try {
        await ensureInputActivityTable(db);
        if (charName) {
            const act = await dbGet(db, `SELECT COUNT(*) AS c FROM api_log WHERE char_name=? AND created_at>? AND (path LIKE '%/missions/%' OR path LIKE '%/dungeon/%' OR path LIKE '%/character%' OR path LIKE '%/inventory%')`, [charName, cutoff]);
            const activity = Number(act?.c || 0);
            if (activity < 20) return flags;
            const rep = await dbGet(db, `SELECT SUM(has_input) AS input, COUNT(*) AS total FROM input_activity WHERE char_name=? AND created_at>?`, [charName, cutoff]);
            const total = Number(rep?.total || 0);
            const input = Number(rep?.input || 0);
            if (total >= 30 && input === 0) {
                flags.push([charName, `No human input: ${activity} game actions in 6h, ${total} input reports, 0 with input`]);
            }
            return flags;
        }
        const actRows = await db.execute({ sql: `SELECT char_name, COUNT(*) AS c FROM api_log WHERE created_at>? AND (path LIKE '%/missions/%' OR path LIKE '%/dungeon/%' OR path LIKE '%/character%' OR path LIKE '%/inventory%') GROUP BY char_name`, args: [cutoff] });
        const actMap = {};
        for (const r of actRows.rows) {
            if (r.char_name && r.char_name !== '?') actMap[r.char_name] = Number(r.c || 0);
        }
        const repRows = await db.execute({ sql: `SELECT char_name, SUM(has_input) AS input, COUNT(*) AS total FROM input_activity WHERE created_at>? GROUP BY char_name`, args: [cutoff] });
        for (const r of repRows.rows) {
            const name = r.char_name;
            if (!name || name === '?') continue;
            if (scanEnabledSet && !scanEnabledSet.has(name)) continue;
            if (!actMap[name]) continue;
            const total = Number(r.total || 0);
            const input = Number(r.input || 0);
            if (actMap[name] >= 20 && total >= 30 && input === 0) {
                flags.push([name, `No human input: ${actMap[name]} game actions in 6h, ${total} input reports, 0 with input`]);
            }
        }
        return flags;
    } catch (e) { console.error('[bot-detect] no human input error:', e.message); return flags; }
}

async function persistBotFlags(db, botPlayers) {
    const now = Math.floor(Date.now() / 1000);
    try {
        await ensureFlaggedTable(db);

        // Always save detection results (manual scans, 🟢 chars when global OFF, etc.)
        const flaggedRows = await db.execute('SELECT char_name FROM flagged_characters');
        const existingFlags = new Set(flaggedRows.rows.map(r => r.char_name));
        for (const [bp, reason] of botPlayers) {
            if (!bp || bp === '?') continue;
            const reasonType = (reason.split(':')[0] || reason).trim().slice(0, 100);
            if (existingFlags.has(bp)) {
                const cur = await dbGet(db, 'SELECT signal_types, last_seen_at, reason FROM flagged_characters WHERE char_name=?', [bp]);
                const types = cur?.signal_types ? cur.signal_types.split(',').filter(Boolean) : [];
                const isNewType = !types.includes(reasonType);
                if (isNewType) types.push(reasonType);
                var isFresh = (cur?.last_seen_at || 0) > now - 120;
                if (isFresh && !isNewType) {
                    await db.execute({
                        sql: 'UPDATE flagged_characters SET reason=?, last_seen_at=? WHERE char_name=?',
                        args: [reason, now, bp]
                    });
                } else {
                    await db.execute({
                        sql: 'UPDATE flagged_characters SET reason=?, signal_count=signal_count+1, signal_types=?, distinct_signals=?, last_seen_at=? WHERE char_name=?',
                        args: [reason, types.join(','), types.length, now, bp]
                    });
                    await logFlagEvent(db, bp, reason, reasonType);
                }
            } else {
                await db.execute({
                    sql: 'INSERT OR IGNORE INTO flagged_characters (char_name, reason, detected_at, last_seen_at, signal_count, distinct_signals, signal_types) VALUES (?,?,?,?,1,1,?)',
                    args: [bp, reason, now, now, reasonType]
                });
                await logFlagEvent(db, bp, reason, reasonType);
            }
        }

        // Only clear stale flags when global scan is ON (prevent wiping when only 🟢 chars are scanned)
        const setting = await dbGet(db, "SELECT value FROM server_settings WHERE key='bot_detection_enabled'");
        const globalOn = !(setting && setting.value === 'false');
        if (globalOn) {
            const detectedNames = new Set([...botPlayers.keys()].filter(n => n && n !== '?'));
            for (const flagged of flaggedRows.rows) {
                if (detectedNames.has(flagged.char_name)) continue;
                const flaggedData = await dbGet(db, 'SELECT reason, signal_types FROM flagged_characters WHERE char_name=?', [flagged.char_name]);
                if (!flaggedData) continue;
                const sTypes = (flaggedData.signal_types || '').split(',').filter(Boolean);
                const hasNonDetectionFlag = sTypes.some(t => !['Managed test bot', 'Instant collect', 'No UI tick', 'Mission timing', 'Battle timing', 'State polling', 'No human input'].includes(t));
                if (hasNonDetectionFlag) continue;
                const isDetectionFlag = sTypes.some(t => ['Managed test bot', 'Instant collect', 'No UI tick', 'Mission timing', 'Battle timing', 'State polling', 'No human input'].includes(t));
                if (!isDetectionFlag) continue;
                await db.execute({ sql: "UPDATE flagged_characters SET reason='No longer detected', confirmed=0 WHERE char_name=? AND confirmed=0", args: [flagged.char_name] });
            }
        }
    } catch (e) { console.error('[persistBotFlags]', e.message); }
}

