// ── Elemental combat helpers ────────────────────────────────────────────
function buildElementalFighter(elem, playerLevel) {
    if (!elem) return null;
    const stats = calcElemStats(elem);
    const elemLvl = elem.element_level || 1;
    // Elemental damage from affinities — higher affinity = more elemental damage
    const affPyro = Number(elem.pyro_affinity || 0);
    const affWater = Number(elem.water_affinity || 0);
    const affElectro = Number(elem.electro_affinity || 0);
    const affWind = Number(elem.wind_affinity || 0);
    const totalAff = affPyro + affWater + affElectro + affWind;
    let elems;
    if (totalAff === 0) {
        // Fresh elemental — use base element at full value
        elems = { pyro: 0, water: 0, wind: 0, electro: 0 };
        elems[elem.element || 'pyro'] = 1;
    } else {
        const maxAff = Math.max(affPyro, affWater, affElectro, affWind);
        elems = {
            pyro:    affPyro / maxAff,
            water:   affWater / maxAff,
            wind:    affWind / maxAff,
            electro: affElectro / maxAff,
        };
    }
    return {
        id: `elem_${elem.id}`,
        name: elem.name || 'Elemental',
        class: 'elemental',
        level: elem.level,
        hp: elem.hp_current ?? stats.hpMax,
        hpMax: stats.hpMax,
        dmgMin: stats.dmgMin,
        dmgMax: stats.dmgMax,
        strength: stats.str,
        magic: stats.mag,
        defense: stats.def,
        armor: Math.floor(stats.def / 3),
        hit_chance: 0,
        crit_chance: 0,
        dmg_bonus: 0,
        elem_dmg: elems,
        elem_resist: { pyro: 0, water: 0, wind: 0, electro: 0 },
        skillEffects: [],
        skillMods: [],
        baseActiveSkills: {},
        activeSkills: {},
        attackZones: DEFAULT_ATTACK_ZONES,
        blockZones: DEFAULT_BLOCK_ZONES,
        isElemental: true,
    };
}

function applyElementalCombat(elemFighter, defender, log, round) {
    if (!elemFighter || elemFighter.hp <= 0) return { dmg: 0, logLine: '' };
    const atkZone = (elemFighter.attackZones || DEFAULT_ATTACK_ZONES)[(round - 1) % 10] || 'chest';
    const blkZone = (defender.blockZones || DEFAULT_BLOCK_ZONES)[(round - 1) % 10] || 'cross_guard';
    const res = simulateRound(round, elemFighter, defender, atkZone, blkZone, false,
        { active: false, value: 0, remaining: 0 }, { active: false, value: 0, remaining: 0 });
    defender.hp = Math.max(0, defender.hp - res.damageDealt);
    if (res.damageDealt > 0) {
        log.push(`🔥 ${elemFighter.name} attacks ${defender.name} for ${res.damageDealt} damage!`);
    }
    return { dmg: res.damageDealt, logLine: res.logLine };
}

function escapeHtml(str) {
    if (!str) return '';
    return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

// Helper to check if character is currently training
async function isCharacterTraining(db, characterId) {
    const training = await dbGet(db, 'SELECT * FROM skill_training WHERE char_id = ? AND ends_at > ?',
        [characterId, Math.floor(Date.now() / 1000)]);
    return !!training;
}

// ── Auto Upkeep Scheduler ──────────────────────────────────────────────────
// Processes upkeep at most once per UTC day, inside a short window after 00:00.
// If a scheduled window is missed (server down / restart mid-day), the day is
// skipped and the tick waits for the next day — so a restart can never re-deduct
// gold or re-activate the squad stat discount mid-day.
const UPKEEP_TICK_WINDOW = 600; // seconds after 00:00 UTC in which the tick may run
async function autoProcessUpkeep(db) {
    try {
        try { await db.execute({ sql: `CREATE TABLE IF NOT EXISTS server_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '')`, args: [] }); } catch {}
        const now = Math.floor(Date.now() / 1000);
        const day = 86400;
        const todayIdx = Math.floor(now / day);
        const lastRow = await dbGet(db, "SELECT value FROM server_settings WHERE key='upkeep_last_process_day'", []);
        const lastDay = Number(lastRow?.value || 0);
        if (lastDay === todayIdx) return;
        if ((now - todayIdx * day) > UPKEEP_TICK_WINDOW) return;
        const ownedBases = await dbAll(db, `SELECT cb.*, su.upgrade_level, su.last_upkeep_paid, su.squad_id, su.base_id
            FROM clan_bases cb JOIN squad_base_upgrades su ON su.base_id = cb.id AND su.squad_id = cb.owner_squad_id
            WHERE cb.owner_squad_id IS NOT NULL AND su.upgrade_level > 0`, []);
        for (const base of ownedBases) {
            try {
                const lastPaid = Number(base.last_upkeep_paid || 0);
                if (lastPaid > 0 && (now - lastPaid) < day) continue;
                const totalLevel = await getSquadTotalLevel(db, base.owner_squad_id);
                const cost = calcBaseUpkeep(base.tier, Number(base.upgrade_level || 0), totalLevel);
                if (cost <= 0) continue;
                const treasury = await dbGet(db, 'SELECT gold FROM squad_treasury WHERE squad_id=?', [base.owner_squad_id]);
                const gold = Number(treasury?.gold || 0);
                if (gold < cost) continue;
                await dbRun(db, 'UPDATE squad_treasury SET gold=gold-? WHERE squad_id=?', [cost, base.owner_squad_id]);
                // Snap to 00:00 UTC
                const paidAt = Math.floor(now / 86400) * 86400;
                await dbRun(db, 'UPDATE squad_base_upgrades SET last_upkeep_paid=?, upkeep_paid_by=NULL WHERE squad_id=? AND base_id=?', [paidAt, base.squad_id, base.base_id]);
            } catch (e) { console.error(`[Upkeep] base ${base.id}:`, e.message); }
        }
        await dbRun(db, "INSERT OR REPLACE INTO server_settings (key, value) VALUES ('upkeep_last_process_day', ?)", [String(todayIdx)]);
    } catch (e) { console.error('[Upkeep] tick error:', e.message); }
}

async function checkAndAwardWeeklyDamageAchievements(db, charId, weeklyDamage) {
    const weeklyDamageAchievements = ACHIEVEMENTS.filter(a => a.chain === 'weekly_damage');
    for (const achievement of weeklyDamageAchievements) {
        if (weeklyDamage >= achievement.target) {
            const alreadyClaimed = await dbGet(db, 'SELECT 1 FROM character_achievements WHERE char_id = ? AND achievement_id = ?', [charId, achievement.id]);
            if (!alreadyClaimed) {
                await db.execute({
                    sql: 'INSERT INTO character_achievements (char_id, achievement_id, claimed_at) VALUES (?, ?, ?)',
                    args: [charId, achievement.id, Math.floor(Date.now() / 1000)]
                });
                console.log(`[Achievements] Character ${charId} awarded ${achievement.id} for ${weeklyDamage} damage.`);
            }
        }
    }
}

async function checkAndAwardWarDamageAchievements(db, charId, warDamage) {
    const warAchievements = ACHIEVEMENTS.filter(a => a.chain === 'war_damage');
    for (const achievement of warAchievements) {
        if (warDamage >= achievement.target) {
            const alreadyClaimed = await dbGet(db, 'SELECT 1 FROM character_achievements WHERE char_id = ? AND achievement_id = ?', [charId, achievement.id]);
            if (!alreadyClaimed) {
                await db.execute({
                    sql: 'INSERT INTO character_achievements (char_id, achievement_id, claimed_at) VALUES (?, ?, ?)',
                    args: [charId, achievement.id, Math.floor(Date.now() / 1000)]
                });
                console.log(`[Achievements] Character ${charId} awarded war_damage ${achievement.id} for ${warDamage} total war damage.`);
            }
        }
    }
}

async function migrateBase64Logos() {
    try {
        const db = await getDb();
        const rows = await dbAll(db, "SELECT id, logo FROM squads WHERE logo LIKE 'data:%'", []);
        if (!rows.length) return;
        console.log(`[Logo Migration] Converting ${rows.length} base64 logo(s) to files...`);
        for (const row of rows) {
            try {
                const matches = row.logo.match(/^data:image\/([^;]+);base64,(.+)$/);
                if (!matches) continue;
                const ext = matches[1] === 'jpeg' ? 'jpg' : matches[1];
                const extJpg = ext === 'jpg' || ext === 'jpeg' ? 'jpg' : ext;
                const filename = `squad-${row.id}.${extJpg}`;
                const filePath = path.join(SQUAD_IMG_DIR, filename);
                const buf = Buffer.from(matches[2], 'base64');
                fs.writeFileSync(filePath, buf);
                const logoUrl = '/images/squads/' + filename;
                await dbRun(db, 'UPDATE squads SET logo=? WHERE id=?', [logoUrl, row.id]);
                console.log(`  Squad ${row.id}: ${logoUrl}`);
            } catch (e) { console.error(`  Squad ${row.id}: ${e.message}`); }
        }
    } catch (e) { console.error('[Logo Migration] Error:', e.message); }
}

async function backfillWeeklyPerformance() {
    try {
        const db = await getDb();
        const weekStart = getCurrentWeekStart();
        const existing = await dbGet(db, 'SELECT 1 FROM character_weekly_performance WHERE week_start=? LIMIT 1', [weekStart]);
        if (existing) return; // Already has data for this week
        const now = Math.floor(Date.now() / 1000);
        console.log('[WeeklyPerf] Backfilling current week performance data...');
        // Aggregate from battles (PvP)
        const battleRows = await dbAll(db, `
            SELECT char_id, SUM(dmg) AS total_dmg, SUM(wins) AS total_wins, SUM(bats) AS total_bats
            FROM (
                SELECT attacker_id AS char_id, COALESCE(total_dmg_dealt,0) AS dmg,
                    CASE WHEN COALESCE(winner_id,0)=attacker_id THEN 1 ELSE 0 END AS wins, 1 AS bats
                FROM battles WHERE fought_at >= ? AND fought_at < ?
                UNION ALL
                SELECT defender_id AS char_id, COALESCE(total_dmg_taken,0) AS dmg,
                    CASE WHEN COALESCE(winner_id,0)=defender_id THEN 1 ELSE 0 END AS wins, 1 AS bats
                FROM battles WHERE defender_id>0 AND fought_at >= ? AND fought_at < ?
            ) GROUP BY char_id
        `, [weekStart, now, weekStart, now]);
        for (const r of battleRows) {
            const cid = Number(r.char_id);
            await incrementWeeklyPerformance(db, cid, Number(r.total_dmg||0), Number(r.total_wins||0)>0, weekStart);
        }
        // Aggregate from messages (missions)
        const msgRows = await dbAll(db, `
            SELECT receiver_id AS char_id,
                COALESCE(SUM(json_extract(substr(body,15),'$.totalDmgDealt')),0) AS total_dmg,
                COALESCE(SUM(CASE WHEN json_extract(substr(body,15),'$.won')=1 THEN 1 ELSE 0 END),0) AS total_wins
            FROM messages WHERE body LIKE 'BATTLE_REPORT:%'
                AND json_extract(substr(body,15),'$.type')='mission'
                AND sent_at >= ? AND sent_at < ?
            GROUP BY receiver_id
        `, [weekStart, now]);
        for (const r of msgRows) {
            const cid = Number(r.char_id);
            const dmg = Number(r.total_dmg||0);
            const wins = Number(r.total_wins||0);
            if (dmg > 0 || wins > 0) {
                await incrementWeeklyPerformance(db, cid, dmg, wins>0, weekStart);
            }
        }
        console.log('[WeeklyPerf] Backfill complete.');
    } catch (e) { console.error('[WeeklyPerf] Backfill error:', e.message); }
}

